"use client";

import Image from "next/image";
import Link from "next/link";
import { createContext, useContext, useEffect, useId, useMemo, useRef, useState } from "react";
import { AdminPanel } from "./admin-panel";
import type { CoinFlow, DashboardData, MarketMover, PulseFill, WalletRow } from "@/lib/hyperliquid";
import { activityKind, displayCoin, marketIdentity, mergePulseFills, tradeFills, type MarketTrade } from "@/lib/live";
import { findConfluences } from "@/lib/stats";
import { defaultNotificationSettings, type NotificationSettings } from "@/lib/notifications";
import { defaultUserPreferences, normalizeUserPreferences, type UserLanguage, type UserPreferences } from "@/lib/user-preferences";
import {
  defaultActivityFilters, defaultWalletFilters, fillsCsv, filterActivity, filterWallets,
  qualityBand, walletInsights, walletRiskFlags, walletsCsv,
  type ActivityFilters, type WalletFilters, type WalletSort,
} from "@/lib/workspace";

type Tab = "overview" | "wallets" | "pulse" | "favorites" | "account" | "admin";
type SettingsSection = "general" | "interface" | "ranking" | "feed" | "notifications";
type IconName = "home" | "pulse" | "wallet" | "star" | "user" | "search" | "arrow" | "refresh" | "shield" | "settings" | "copy" | "download" | "filter" | "close" | "command" | "eye";
type SessionState = { user: { id: string; firstName: string; lastName: string; username: string }; isAdmin: boolean; initData: string };
type NotificationProfile = { favorites: string[]; settings: NotificationSettings; preferences: UserPreferences; chatLinked: boolean };
type TapeItem = { id: string; coin: string; action: string; kind: "gain" | "loss" | "neutral"; wallet: string; walletName: string; notional: number; price: number; time: number };
type Preset = { id: string; name: string; filters: WalletFilters; sort: WalletSort; direction: "asc" | "desc" };
type SavedWorkspace = { favorites?: string[]; notes?: Record<string, string>; tags?: Record<string, string>; recent?: string[]; presets?: Preset[]; preferences?: UserPreferences; density?: "compact" | "comfortable"; privacy?: boolean; compactNumbers?: boolean; absoluteTime?: boolean; tickerPaused?: boolean; hiddenMarkets?: string[]; signalThreshold?: number; confluenceMinutes?: number };
type NavItem = { id: Tab; label: string; mobileLabel?: string; icon: IconName };

declare global { interface Window { Telegram?: { WebApp?: { initData?: string; ready(): void; expand(): void; version?: string; setHeaderColor(color: string): void; setBackgroundColor(color: string): void } } } }

const navItems = (language: UserLanguage): NavItem[] => language === "en" ? [
  { id: "overview", label: "Overview", icon: "home" },
  { id: "wallets", label: "Traders", mobileLabel: "Top", icon: "wallet" },
  { id: "pulse", label: "Activity", mobileLabel: "Feed", icon: "pulse" },
  { id: "favorites", label: "Favorites", mobileLabel: "Mine", icon: "star" },
  { id: "account", label: "Account", mobileLabel: "Profile", icon: "user" },
] : [
  { id: "overview", label: "Главная", icon: "home" },
  { id: "wallets", label: "Трейдеры", mobileLabel: "Топ", icon: "wallet" },
  { id: "pulse", label: "Активность", mobileLabel: "Лента", icon: "pulse" },
  { id: "favorites", label: "Избранное", mobileLabel: "Мои", icon: "star" },
  { id: "account", label: "Кабинет", mobileLabel: "Профиль", icon: "user" },
];
const text = (language: UserLanguage, ru: string, en: string) => language === "en" ? en : ru;
const LanguageContext = createContext<UserLanguage>("ru");
const useT = () => { const language = useContext(LanguageContext); return (ru: string, en: string) => text(language, ru, en); };
const warningText = (language: UserLanguage, warning: string) => text(language, warning, ({ "Рейтинг временно недоступен": "Ranking is temporarily unavailable", "Котировки временно недоступны": "Quotes are temporarily unavailable", "Часть live-рынков временно недоступна": "Some live markets are temporarily unavailable", "Часть данных Binance и Bybit временно недоступна": "Some Binance and Bybit data is temporarily unavailable", "Нет свежих снимков позиций для сопоставления с движением рынка": "No fresh position snapshots are available for market matching" } as Record<string, string>)[warning] ?? warning);
const riskText = (language: UserLanguage, flag: string) => text(language, flag, ({ "Минус за 24H": "Negative 24H PnL", "Аномальный ROI": "Unusual ROI", "Нет объёма за 24H": "No 24H volume", "Небольшой капитал": "Low capital" } as Record<string, string>)[flag] ?? flag);
const WORKSPACE_KEY = "dc-pulse-workspace-v2";
const short = (address: string) => `${address.slice(0, 6)}…${address.slice(-4)}`;
const rawMoney = (value: number, compact = true, decimals = 2) => new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", notation: compact ? "compact" : "standard", maximumFractionDigits: compact ? 1 : decimals }).format(value);
const price = (value: number) => value >= 1000 ? `$${value.toLocaleString("en-US", { maximumFractionDigits: 0 })}` : `$${value.toLocaleString("en-US", { maximumFractionDigits: 4 })}`;
const relativeTime = (time: number, language: UserLanguage) => { const seconds = Math.max(0, Math.round((Date.now() - time) / 1000)); const units = language === "en" ? ["s", "m", "h", "d"] : ["с", "м", "ч", "д"]; return seconds < 60 ? `${seconds}${units[0]}` : seconds < 3600 ? `${Math.round(seconds / 60)}${units[1]}` : seconds < 86_400 ? `${Math.round(seconds / 3600)}${units[2]}` : `${Math.round(seconds / 86_400)}${units[3]}`; };
const fillToTape = (fill: PulseFill): TapeItem => { const action = activityKind(fill); return { id: `${fill.hash}:${fill.wallet}:${fill.coin}:${fill.time}`, coin: fill.coin, action: action.label, kind: action.kind, wallet: fill.wallet, walletName: fill.walletName, notional: Number(fill.px) * Number(fill.sz), price: Number(fill.px), time: fill.time }; };
const mergeTape = (current: TapeItem[], incoming: TapeItem[]) => [...incoming, ...current].filter((item, index, rows) => rows.findIndex((row) => row.id === item.id) === index).sort((a, b) => b.time - a.time).slice(0, 600);
const download = (name: string, content: string) => { const url = URL.createObjectURL(new Blob([content], { type: "text/csv;charset=utf-8" })); const link = document.createElement("a"); link.href = url; link.download = name; link.click(); setTimeout(() => URL.revokeObjectURL(url), 0); };

export function Dashboard({ initialData }: { initialData: DashboardData }) {
  const [preferences, setPreferences] = useState<UserPreferences>(() => ({ ...defaultUserPreferences, signalThreshold: initialData.config.signalThreshold, confluenceMinutes: initialData.config.confluenceMinutes }));
  const [tab, setTab] = useState<Tab>("overview");
  const [favorites, setFavorites] = useState<Set<string>>(new Set());
  const [notes, setNotes] = useState<Record<string, string>>({});
  const [tags, setTags] = useState<Record<string, string>>({});
  const [recent, setRecent] = useState<string[]>([]);
  const [presets, setPresets] = useState<Preset[]>([]);
  const [walletFilters, setWalletFilters] = useState<WalletFilters>(defaultWalletFilters);
  const [walletSort, setWalletSort] = useState<WalletSort>("rank");
  const [sortDirection, setSortDirection] = useState<"asc" | "desc">("asc");
  const [activityFilters, setActivityFilters] = useState<ActivityFilters>(defaultActivityFilters);
  const [page, setPage] = useState(1); const [pageSize, setPageSize] = useState(25); const [activityLimit, setActivityLimit] = useState(50);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [inspector, setInspector] = useState<WalletRow | null>(null);
  const [compareOpen, setCompareOpen] = useState(false); const [filtersOpen, setFiltersOpen] = useState(false); const [settingsOpen, setSettingsOpen] = useState(false); const [settingsSection, setSettingsSection] = useState<SettingsSection>("general"); const [commandOpen, setCommandOpen] = useState(false); const [commandQuery, setCommandQuery] = useState("");
  const [density, setDensity] = useState<"compact" | "comfortable">("compact"); const [privacy, setPrivacy] = useState(false); const [compactNumbers, setCompactNumbers] = useState(true); const [absoluteTime, setAbsoluteTime] = useState(false); const [tickerPaused, setTickerPaused] = useState(false); const [hiddenMarkets, setHiddenMarkets] = useState<Set<string>>(new Set());
  const [signalThreshold, setSignalThreshold] = useState(initialData.config.signalThreshold); const [confluenceMinutes, setConfluenceMinutes] = useState(initialData.config.confluenceMinutes);
  const [fills, setFills] = useState(initialData.fills); const [tape, setTape] = useState(() => mergeTape([], initialData.fills.map(fillToTape))); const [prices, setPrices] = useState(initialData.prices);
  const [live, setLive] = useState(false); const [online, setOnline] = useState(true); const [lastMessage, setLastMessage] = useState(initialData.updatedAt); const [reconnects, setReconnects] = useState(0); const [session, setSession] = useState<SessionState | null>(null); const [toast, setToast] = useState("");
  const [clock, setClock] = useState(initialData.updatedAt);
  const [notificationSettings, setNotificationSettings] = useState(defaultNotificationSettings); const [chatLinked, setChatLinked] = useState(false); const [notificationSaving, setNotificationSaving] = useState(false);

  const currentPreferences = (): UserPreferences => normalizeUserPreferences({
    ...preferences, density, privacy, compactNumbers, absoluteTime, tickerPaused, hiddenMarkets: [...hiddenMarkets], signalThreshold, confluenceMinutes,
    walletSort, sortDirection, pageSize, walletPerformance: walletFilters.performance, minAccount: walletFilters.minAccount,
    minMonthPnl: walletFilters.minMonthPnl, minRoi: walletFilters.minRoi, minVolume: walletFilters.minVolume,
    namedOnly: walletFilters.namedOnly, favoritesOnly: walletFilters.favoritesOnly, riskFreeOnly: walletFilters.riskFreeOnly,
    activityCoin: activityFilters.coin, activityAction: activityFilters.action, activityFavoritesOnly: activityFilters.favoritesOnly,
    activityMinNotional: activityFilters.minNotional, activitySort: activityFilters.sort, activityLimit,
  });
  const applyPreferences = (value: UserPreferences, moveToStart = false) => {
    const next = normalizeUserPreferences(value); setPreferences(next); if (moveToStart) setTab(next.startTab); setDensity(next.density); setPrivacy(next.privacy);
    setCompactNumbers(next.compactNumbers); setAbsoluteTime(next.absoluteTime); setTickerPaused(next.tickerPaused); setHiddenMarkets(new Set(next.hiddenMarkets));
    setSignalThreshold(next.signalThreshold); setConfluenceMinutes(next.confluenceMinutes); setWalletSort(next.walletSort); setSortDirection(next.sortDirection);
    setPageSize(next.pageSize); setActivityLimit(next.activityLimit);
    setWalletFilters((current) => ({ ...current, performance: next.walletPerformance, minAccount: next.minAccount, minMonthPnl: next.minMonthPnl, minRoi: next.minRoi, minVolume: next.minVolume, namedOnly: next.namedOnly, favoritesOnly: next.favoritesOnly, riskFreeOnly: next.riskFreeOnly }));
    setActivityFilters((current) => ({ ...current, coin: next.activityCoin, action: next.activityAction, favoritesOnly: next.activityFavoritesOnly, minNotional: next.activityMinNotional, sort: next.activitySort }));
  };
  const updatePreference = <K extends keyof UserPreferences>(key: K, value: UserPreferences[K]) => {
    const next = normalizeUserPreferences({ ...currentPreferences(), [key]: value }); applyPreferences(next); saveWorkspace({ preferences: next }); return next;
  };

  const saveWorkspace = (patch: Partial<SavedWorkspace>) => { try { const current = JSON.parse(localStorage.getItem(WORKSPACE_KEY) ?? "{}") as SavedWorkspace; localStorage.setItem(WORKSPACE_KEY, JSON.stringify({ ...current, ...patch })); } catch { localStorage.removeItem(WORKSPACE_KEY); } };
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(""), 1800); };
  const copy = async (value: string, message = text(preferences.language, "Скопировано", "Copied")) => { try { await navigator.clipboard.writeText(value); notify(message); } catch { notify(text(preferences.language, "Не удалось скопировать", "Could not copy")); } };
  const formatMoney = (value: number) => privacy ? "••••" : rawMoney(value, compactNumbers, preferences.moneyDecimals);
  const formatTime = (time: number) => {
    if (!absoluteTime) return relativeTime(time, preferences.language);
    if (preferences.dateFormat === "iso") return new Date(time).toISOString().slice(0, 16).replace("T", " ");
    return new Intl.DateTimeFormat(preferences.language === "en" ? "en-US" : "ru-RU", { day: "2-digit", month: preferences.dateFormat === "full" ? "long" : "short", hour: "2-digit", minute: "2-digit", hour12: preferences.timeFormat === "12h", timeZone: preferences.timeZone === "local" ? undefined : preferences.timeZone }).format(time);
  };
  const persistNotifications = async (nextFavorites: string[], nextSettings: NotificationSettings, announce = false, preferenceOverride?: UserPreferences) => {
    const nextPreferences = preferenceOverride ?? currentPreferences(); saveWorkspace({ favorites: nextFavorites, preferences: nextPreferences });
    if (!session) { if (announce) notify(text(nextPreferences.language, "Настройки сохранены на этом устройстве", "Settings saved on this device")); return; }
    setNotificationSaving(true);
    try {
      const response = await fetch("/api/notifications", { method: "PUT", headers: { "content-type": "application/json" }, body: JSON.stringify({ initData: session.initData, favorites: nextFavorites, settings: nextSettings, preferences: nextPreferences }) });
      if (!response.ok) throw new Error();
      const profile = await response.json() as NotificationProfile;
      setFavorites(new Set(profile.favorites)); setNotificationSettings(profile.settings); setChatLinked(profile.chatLinked); applyPreferences(profile.preferences);
      if (announce) notify(text(profile.preferences.language, "Личные настройки сохранены", "Personal settings saved"));
    } catch { notify(text(preferences.language, "Не удалось сохранить настройки", "Could not save settings")); } finally { setNotificationSaving(false); }
  };

  useEffect(() => {
    const webApp = window.Telegram?.WebApp; webApp?.ready(); webApp?.expand();
    if (webApp && Number(webApp.version ?? 0) >= 6.1) { webApp.setHeaderColor("#000000"); webApp.setBackgroundColor("#000000"); }
    const telegramData = webApp?.initData ?? "";
    let localFavorites: string[] = []; let localPreferences: UserPreferences | undefined;
    try {
      const saved = JSON.parse(localStorage.getItem(WORKSPACE_KEY) ?? "{}") as SavedWorkspace;
      localFavorites = Array.isArray(saved.favorites) ? saved.favorites.filter((item): item is string => typeof item === "string") : [];
      localPreferences = saved.preferences ? normalizeUserPreferences(saved.preferences) : undefined;
      queueMicrotask(() => {
        if (localFavorites.length) setFavorites(new Set(localFavorites));
        if (saved.notes && typeof saved.notes === "object") setNotes(saved.notes); if (saved.tags && typeof saved.tags === "object") setTags(saved.tags);
        if (Array.isArray(saved.recent)) setRecent(saved.recent.filter((item): item is string => typeof item === "string").slice(0, 8)); if (Array.isArray(saved.presets)) setPresets(saved.presets.filter((item) => item && typeof item.name === "string").slice(0, 8));
        if (saved.density === "compact" || saved.density === "comfortable") setDensity(saved.density); if (typeof saved.privacy === "boolean") setPrivacy(saved.privacy); if (typeof saved.compactNumbers === "boolean") setCompactNumbers(saved.compactNumbers); if (typeof saved.absoluteTime === "boolean") setAbsoluteTime(saved.absoluteTime); if (typeof saved.tickerPaused === "boolean") setTickerPaused(saved.tickerPaused);
        if (Array.isArray(saved.hiddenMarkets)) setHiddenMarkets(new Set(saved.hiddenMarkets)); if (typeof saved.signalThreshold === "number" && saved.signalThreshold >= 0) setSignalThreshold(saved.signalThreshold); if (typeof saved.confluenceMinutes === "number" && saved.confluenceMinutes >= 5) setConfluenceMinutes(saved.confluenceMinutes);
        if (localPreferences) applyPreferences(localPreferences, true);
      });
    } catch { localStorage.removeItem(WORKSPACE_KEY); }
    void (async () => {
      try {
        const sessionResponse = await fetch("/api/session", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ initData: telegramData }) });
        if (!sessionResponse.ok) return;
        const value = await sessionResponse.json() as Omit<SessionState, "initData">; const nextSession = { ...value, initData: telegramData }; setSession(nextSession);
        const profileResponse = await fetch("/api/notifications", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ initData: telegramData }) });
        if (!profileResponse.ok) return;
        let profile = await profileResponse.json() as NotificationProfile;
        const migratePreferences = localPreferences && JSON.stringify(profile.preferences) === JSON.stringify(defaultUserPreferences);
        if ((!profile.favorites.length && localFavorites.length) || migratePreferences) {
          const migration = await fetch("/api/notifications", { method: "PUT", headers: { "content-type": "application/json" }, body: JSON.stringify({ initData: telegramData, favorites: profile.favorites.length ? profile.favorites : localFavorites, settings: profile.settings, preferences: migratePreferences ? localPreferences : profile.preferences }) });
          if (migration.ok) profile = await migration.json() as NotificationProfile;
        }
        setFavorites(new Set(profile.favorites)); setNotificationSettings(profile.settings); setChatLinked(profile.chatLinked); applyPreferences(profile.preferences, true); saveWorkspace({ favorites: profile.favorites, preferences: profile.preferences });
      } catch { /* local workspace remains available offline */ }
    })();
    const onOnline = () => setOnline(true); const onOffline = () => setOnline(false); window.addEventListener("online", onOnline); window.addEventListener("offline", onOffline);
    return () => { window.removeEventListener("online", onOnline); window.removeEventListener("offline", onOffline); };
  }, []);

  useEffect(() => { const focusSearch = () => document.querySelector<HTMLInputElement>("#wallet-search")?.focus(); const onKey = (event: KeyboardEvent) => { if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") { event.preventDefault(); setCommandOpen((value) => !value); } if (event.key === "/" && !["INPUT", "TEXTAREA", "SELECT"].includes((event.target as HTMLElement).tagName)) { event.preventDefault(); setTab("wallets"); setTimeout(focusSearch, 0); } if (event.key === "Escape") { setCommandOpen(false); setSettingsOpen(false); setCompareOpen(false); setInspector(null); } }; window.addEventListener("keydown", onKey); return () => window.removeEventListener("keydown", onKey); }, []);

  useEffect(() => { document.documentElement.lang = preferences.language; document.documentElement.style.fontSize = preferences.fontScale === "small" ? "14px" : preferences.fontScale === "large" ? "18px" : "16px"; }, [preferences.fontScale, preferences.language]);
  useEffect(() => { const timer = window.setInterval(() => setClock(Date.now()), 10_000); return () => window.clearInterval(timer); }, []);

  useEffect(() => {
    if (!initialData.liveCoins.length) return;
    const names = new Map(initialData.wallets.map((wallet) => [wallet.address.toLowerCase(), wallet.name])); let socket: WebSocket | undefined; let retry: ReturnType<typeof setTimeout> | undefined; let heartbeat: ReturnType<typeof setInterval> | undefined; let stopped = false;
    const connect = () => {
      socket = new WebSocket("wss://api.hyperliquid.xyz/ws");
      socket.onopen = () => { setLive(true); socket?.send(JSON.stringify({ method: "subscribe", subscription: { type: "allMids" } })); for (const wallet of initialData.tracked) socket?.send(JSON.stringify({ method: "subscribe", subscription: { type: "userFills", user: wallet.address, aggregateByTime: true } })); for (const coin of initialData.liveCoins) socket?.send(JSON.stringify({ method: "subscribe", subscription: { type: "trades", coin } })); heartbeat = setInterval(() => socket?.readyState === WebSocket.OPEN && socket.send(JSON.stringify({ method: "ping" })), 45_000); };
      socket.onmessage = ({ data }) => { setLastMessage(Date.now()); try { const message = JSON.parse(data); if (message.channel === "allMids") { const mids = message.data?.mids ?? {}; setPrices((current) => Object.fromEntries(Object.keys(current).map((coin) => [coin, Number(mids[coin] ?? current[coin])]))); } if (message.channel === "userFills") { const payload = message.data; const wallet = String(payload?.user ?? "").toLowerCase(); const incoming = (payload?.fills ?? []).map((fill: PulseFill) => ({ ...fill, coin: displayCoin(fill.coin, initialData.coinNames), wallet, walletName: names.get(wallet) ?? short(wallet), source: "user" as const })); if (incoming.length) { setFills((current) => mergePulseFills(current, incoming)); setTape((current) => mergeTape(current, incoming.map(fillToTape))); } } if (message.channel === "trades") { const incoming = tradeFills(message.data as MarketTrade[], names, initialData.coinNames); if (incoming.length) { setFills((current) => mergePulseFills(current, incoming)); setTape((current) => mergeTape(current, incoming.map(fillToTape))); } } } catch { /* malformed transport message */ } };
      socket.onclose = () => { setLive(false); clearInterval(heartbeat); if (!stopped) { setReconnects((value) => value + 1); retry = setTimeout(connect, 3_000); } }; socket.onerror = () => socket?.close();
    };
    connect(); return () => { stopped = true; clearTimeout(retry); clearInterval(heartbeat); socket?.close(); };
  }, [initialData.coinNames, initialData.liveCoins, initialData.tracked, initialData.wallets]);

  const toggleFavorite = (address: string) => setFavorites((current) => { const next = new Set(current); if (next.has(address)) next.delete(address); else next.add(address); saveWorkspace({ favorites: [...next] }); void persistNotifications([...next], notificationSettings); return next; });
  const rememberWallet = (address: string) => setRecent((current) => { const next = [address, ...current.filter((item) => item !== address)].slice(0, 8); saveWorkspace({ recent: next }); return next; });
  const openSettings = (section: SettingsSection = "general") => { setSettingsSection(section); setSettingsOpen(true); };
  const toggleSelected = (address: string) => setSelected((current) => { const next = new Set(current); if (next.has(address)) next.delete(address); else if (next.size < 4) next.add(address); else notify(text(preferences.language, "Можно сравнить до 4 кошельков", "You can compare up to 4 wallets")); return next; });
  const resetWalletFilters = () => { setWalletFilters(defaultWalletFilters); setWalletSort("rank"); setSortDirection("asc"); setPage(1); };
  const savePreset = () => { const next = [...presets, { id: crypto.randomUUID(), name: `${text(preferences.language, "Набор", "Preset")} ${presets.length + 1}`, filters: walletFilters, sort: walletSort, direction: sortDirection }].slice(-8); setPresets(next); saveWorkspace({ presets: next }); notify(text(preferences.language, "Набор фильтров сохранён", "Filter preset saved")); };
  const applyPreset = (preset: Preset) => { setWalletFilters(preset.filters); setWalletSort(preset.sort); setSortDirection(preset.direction); setPage(1); }; const removePreset = (id: string) => { const next = presets.filter((item) => item.id !== id); setPresets(next); saveWorkspace({ presets: next }); };

  const filteredWallets = useMemo(() => { const rows = filterWallets(initialData.wallets, walletFilters, favorites, walletSort, sortDirection); return preferences.favoritesFirst ? rows.sort((a, b) => Number(favorites.has(b.address)) - Number(favorites.has(a.address))) : rows; }, [initialData.wallets, walletFilters, favorites, walletSort, sortDirection, preferences.favoritesFirst]);
  const walletPageCount = Math.max(1, Math.ceil(filteredWallets.length / pageSize)); const safePage = Math.min(page, walletPageCount); const visibleWallets = filteredWallets.slice((safePage - 1) * pageSize, safePage * pageSize);
  const favoriteWallets = initialData.wallets.filter((wallet) => favorites.has(wallet.address)); const comparedWallets = initialData.wallets.filter((wallet) => selected.has(wallet.address)); const recentWallets = recent.map((address) => initialData.wallets.find((wallet) => wallet.address === address)).filter((wallet): wallet is WalletRow => Boolean(wallet));
  const insights = walletInsights(filteredWallets); const filteredFills = useMemo(() => filterActivity(fills.filter((fill) => fill.source === "market" ? preferences.showMarketTrades : preferences.showExactTrades), activityFilters, favorites), [fills, activityFilters, favorites, preferences.showExactTrades, preferences.showMarketTrades]); const coins = [...new Set(fills.map((fill) => fill.coin))].sort(); const confluences = findConfluences(fills, clock, confluenceMinutes * 60_000, Object.fromEntries(initialData.wallets.map((wallet) => [wallet.address.toLowerCase(), { quality: wallet.qualityScore, accountValue: wallet.accountValue }]))); const baseNav = navItems(preferences.language); const visibleNav = session?.isAdmin ? [...baseNav, { id: "admin" as const, label: text(preferences.language, "Админ", "Admin"), icon: "shield" as const }] : baseNav;
  const tickerItems = tape.filter((item) => item.notional >= signalThreshold); const activeFilterCount = [walletFilters.performance !== "all", walletFilters.minAccount > 0, walletFilters.minMonthPnl > 0, walletFilters.minRoi > 0, walletFilters.minVolume > 0, walletFilters.namedOnly, walletFilters.favoritesOnly, walletFilters.riskFreeOnly].filter(Boolean).length;
  const fillStats = {
    exact: filteredFills.filter((fill) => fill.source !== "market").length,
    public: filteredFills.filter((fill) => fill.source === "market").length,
    wallets: new Set(filteredFills.map((fill) => fill.wallet)).size,
    notional: filteredFills.reduce((sum, fill) => sum + Math.abs(Number(fill.px) * Number(fill.sz)), 0),
  };
  const commands = [...visibleNav.map((item) => ({ label: `${text(preferences.language, "Открыть", "Open")}: ${item.label}`, detail: text(preferences.language, "Навигация", "Navigation"), run: () => setTab(item.id) })), { label: text(preferences.language, "Найти трейдера", "Find a trader"), detail: text(preferences.language, "Поиск", "Search"), run: () => { setTab("wallets"); setTimeout(() => document.querySelector<HTMLInputElement>("#wallet-search")?.focus(), 0); } }, { label: text(preferences.language, "Экспортировать рейтинг", "Export ranking"), detail: "CSV", run: () => download("dc-pulse-wallets.csv", walletsCsv(filteredWallets)) }, { label: privacy ? text(preferences.language, "Показать суммы", "Show amounts") : text(preferences.language, "Скрыть суммы", "Hide amounts"), detail: text(preferences.language, "Приватность", "Privacy"), run: () => updatePreference("privacy", !privacy) }, { label: text(preferences.language, "Открыть настройки", "Open settings"), detail: text(preferences.language, "Интерфейс", "Interface"), run: () => openSettings() }].filter((item) => `${item.label} ${item.detail}`.toLowerCase().includes(commandQuery.toLowerCase()));

  return <LanguageContext.Provider value={preferences.language}><div lang={preferences.language} data-contrast={preferences.highContrast} data-motion={preferences.reducedMotion ? "reduced" : "full"} data-targets={preferences.largeTargets ? "large" : "normal"} data-font={preferences.fontScale} data-hover={preferences.rowHover ? "on" : "off"} data-zebra={preferences.zebraRows ? "on" : "off"} data-market-strip={preferences.showMarketStrip ? "show" : "hide"} data-summary={preferences.showSummary ? "show" : "hide"} data-confluences={preferences.showConfluences ? "show" : "hide"} data-recent={preferences.showRecent ? "show" : "hide"} data-latest={preferences.showLatest ? "show" : "hide"} data-quality={preferences.showQuality ? "show" : "hide"} data-risk={preferences.showRisk ? "show" : "hide"} data-addresses={preferences.showAddresses ? "show" : "hide"} data-account={preferences.showAccountColumn ? "show" : "hide"} data-day-pnl={preferences.showDayPnlColumn ? "show" : "hide"} data-month-pnl={preferences.showMonthPnlColumn ? "show" : "hide"} data-roi={preferences.showRoiColumn ? "show" : "hide"} data-volume={preferences.showVolumeColumn ? "show" : "hide"} className={`dc-app min-h-dvh bg-[var(--bg)] pb-20 md:pb-0 density-${density}`}>
    <header className={`${preferences.stickyHeader ? "sticky top-0" : "relative"} z-40 border-b border-[var(--line)] bg-[#000000ed] backdrop-blur-xl`}><div className="mx-auto flex h-16 max-w-[1500px] items-center gap-5 px-3 sm:px-5"><button onClick={() => setTab("overview")} aria-label={text(preferences.language, "На главную", "Home")}><Brand/></button><nav className="hidden h-full items-center gap-1 md:flex" aria-label={text(preferences.language, "Основная навигация", "Main navigation")}>{visibleNav.map((item) => <NavButton key={item.id} item={item} active={tab === item.id} onClick={() => setTab(item.id)}/>)}</nav><div className="ml-auto flex items-center gap-2"><button onClick={() => setCommandOpen(true)} className="command-trigger hidden sm:flex"><Icon name="search" size={14}/><span>{text(preferences.language, "Команды", "Commands")}</span><kbd>⌘K</kbd></button><button onClick={() => updatePreference("privacy", !privacy)} className="icon-button" aria-label={privacy ? text(preferences.language, "Показать суммы", "Show amounts") : text(preferences.language, "Скрыть суммы", "Hide amounts")}><Icon name="eye" size={16}/></button><button onClick={() => openSettings()} className="icon-button" aria-label={text(preferences.language, "Настройки", "Settings")}><Icon name="settings" size={16}/></button><button onClick={() => location.reload()} className="icon-button hidden sm:flex" aria-label={text(preferences.language, "Обновить данные", "Refresh data")}><Icon name="refresh" size={16}/></button><span role="status" className={`status-chip ${live && online ? "text-[var(--cyan)]" : "text-[var(--muted)]"}`} title={`${text(preferences.language, "Последнее сообщение", "Last message")}: ${formatTime(lastMessage)} · ${text(preferences.language, "переподключений", "reconnects")}: ${reconnects}`}><i className={`size-1.5 rounded-full ${live && online ? "live-dot bg-[var(--cyan)]" : "bg-[var(--loss)]"}`}/>{!online ? "OFFLINE" : live ? "LIVE" : "CONNECTING"}</span></div></div></header>
    {preferences.showTicker && <ActivityTicker items={tickerItems} paused={tickerPaused} onToggle={() => updatePreference("tickerPaused", !tickerPaused)} money={formatMoney} time={formatTime} onRemember={rememberWallet}/>}
    <main className="mx-auto max-w-[1500px] px-3 py-4 sm:px-5 sm:py-5">
      {preferences.showWarnings && initialData.warnings.map((warning) => <div key={warning} className="mb-3 border border-[#ffc4663b] bg-[#ffc4660b] px-3 py-2 text-xs text-[var(--warn)]">{warningText(preferences.language, warning)}</div>)}
      {tab === "overview" && <Overview
        preferences={preferences} initialData={initialData} prices={prices} hiddenMarkets={hiddenMarkets} insights={insights} wallets={initialData.wallets.slice(0, 12)}
        favorites={favorites} selected={selected} notes={notes} tags={tags} density={density} privacy={privacy} money={formatMoney} time={formatTime}
        fills={fills} confluences={confluences} confluenceMinutes={confluenceMinutes} recentWallets={recentWallets} onTab={setTab} onCopy={copy}
        onFavorite={toggleFavorite} onSelect={toggleSelected} onInspect={setInspector} onRemember={rememberWallet}
        onConfluenceMinutes={(value) => { void updatePreference("confluenceMinutes", value); }}
        onConfluence={(coin, direction) => { setActivityFilters({ ...defaultActivityFilters, coin, action: direction === "LONG" ? "long" : "short" }); setTab("pulse"); }}
      />}
      {tab === "wallets" && <WalletsView wallets={visibleWallets} all={filteredWallets} insights={insights} filters={walletFilters} setFilters={(value) => { setWalletFilters(value); setPage(1); }} sort={walletSort} setSort={(value) => { setWalletSort(value); setPage(1); }} direction={sortDirection} setDirection={setSortDirection} filtersOpen={filtersOpen} setFiltersOpen={setFiltersOpen} activeFilterCount={activeFilterCount} presets={presets} onSavePreset={savePreset} onApplyPreset={applyPreset} onRemovePreset={removePreset} onReset={resetWalletFilters} page={safePage} pages={walletPageCount} pageSize={pageSize} setPage={setPage} setPageSize={(value) => { setPageSize(value); setPage(1); }} favorites={favorites} selected={selected} notes={notes} tags={tags} density={density} privacy={privacy} money={formatMoney} onFavorite={toggleFavorite} onSelect={toggleSelected} onInspect={setInspector} onRemember={rememberWallet} onCopy={copy}/>}
      {tab === "pulse" && <PulseView fills={filteredFills} filters={activityFilters} setFilters={setActivityFilters} coins={coins} stats={fillStats} live={live} limit={activityLimit} setLimit={setActivityLimit} favorites={favorites} money={formatMoney} time={formatTime} onFavorite={toggleFavorite} onRemember={rememberWallet} onCopy={copy} confluences={confluences} confluenceMinutes={confluenceMinutes} exactWallets={initialData.tracked.length} onConfluenceMinutes={(value) => { void updatePreference("confluenceMinutes", value); }} coinFlow={initialData.coinFlow}/>}
      {tab === "favorites" && <FavoritesView wallets={favoriteWallets} favorites={favorites} selected={selected} notes={notes} tags={tags} density={density} privacy={privacy} money={formatMoney} onFavorite={toggleFavorite} onSelect={toggleSelected} onInspect={setInspector} onRemember={rememberWallet} onOpen={() => setTab("wallets")}/>}
      {tab === "account" && <AccountView
        user={session?.user ?? null}
        isAdmin={Boolean(session?.isAdmin)}
        chatLinked={chatLinked}
        favoritesCount={favorites.size}
        notificationSettings={notificationSettings}
        preferences={currentPreferences()}
        onSettings={openSettings}
        onTab={setTab}
        onLanguage={(language) => { const next = updatePreference("language", language); void persistNotifications([...favorites], notificationSettings, false, next); }}
      />}
      {tab === "admin" && session?.isAdmin && <AdminPanel initData={session.initData} liveWallets={initialData.tradeCoverage} exactLiveWallets={initialData.tracked.length} marketCoverage={initialData.liveCoins.length} live={live} events={tape.length} updatedAt={initialData.updatedAt}/>}
    </main>
    {selected.size > 0 && <div className="compare-bar"><div><b>{selected.size} {text(preferences.language, "трейдера", "traders")}</b><span className="hidden sm:inline"> {text(preferences.language, "выбраны для сравнения", "selected for comparison")}</span></div><div className="flex gap-2"><button onClick={() => setSelected(new Set())} className="compact-action">{text(preferences.language, "Очистить", "Clear")}</button><button onClick={() => setCompareOpen(true)} disabled={selected.size < 2} className="compact-action border border-[#5ee3dc55] bg-[#5ee3dc0b] text-[var(--cyan)] disabled:opacity-40">{text(preferences.language, "Сравнить", "Compare")}</button></div></div>}
    {settingsOpen && <SettingsDrawer
      initialSection={settingsSection} notificationSettings={notificationSettings} chatLinked={chatLinked} favoritesCount={favorites.size} notificationSaving={notificationSaving}
      preferences={currentPreferences()} prices={prices} live={live} online={online} reconnects={reconnects} lastMessage={lastMessage} time={formatTime}
      onClose={() => setSettingsOpen(false)} onNotificationSettings={setNotificationSettings} onSaveNotifications={() => void persistNotifications([...favorites], notificationSettings, true)}
      onPreference={updatePreference}
    />}
    {inspector && <WalletInspector wallet={inspector} note={notes[inspector.address] ?? ""} tag={tags[inspector.address] ?? ""} favorite={favorites.has(inspector.address)} money={formatMoney} onFavorite={() => toggleFavorite(inspector.address)} onCopy={copy} onClose={() => setInspector(null)} onSave={(note, tag) => { const nextNotes = { ...notes, [inspector.address]: note }; const nextTags = { ...tags, [inspector.address]: tag }; setNotes(nextNotes); setTags(nextTags); saveWorkspace({ notes: nextNotes, tags: nextTags }); notify(text(preferences.language, "Карточка трейдера сохранена", "Trader card saved")); }}/>}
    {compareOpen && <CompareDialog wallets={comparedWallets} money={formatMoney} onClose={() => setCompareOpen(false)} onRemove={toggleSelected}/>}
    {commandOpen && <CommandPalette query={commandQuery} setQuery={setCommandQuery} commands={commands} onClose={() => { setCommandOpen(false); setCommandQuery(""); }}/>}
    {toast && <div role="status" className="toast">{toast}</div>}
    <nav className="fixed inset-x-0 bottom-0 z-40 flex border-t border-[var(--line)] bg-[#050505f5] px-1 pb-[env(safe-area-inset-bottom)] md:hidden" aria-label={text(preferences.language, "Основная навигация", "Main navigation")}>{visibleNav.map((item) => <NavButton key={item.id} item={item} active={tab === item.id} onClick={() => setTab(item.id)}/>)}</nav>
  </div></LanguageContext.Provider>;
}

function Overview(p: { preferences: UserPreferences; initialData: DashboardData; prices: Record<string, number>; hiddenMarkets: Set<string>; insights: ReturnType<typeof walletInsights>; wallets: WalletRow[]; favorites: Set<string>; selected: Set<string>; notes: Record<string, string>; tags: Record<string, string>; density: "compact" | "comfortable"; privacy: boolean; money(value: number): string; time(value: number): string; fills: PulseFill[]; confluences: ReturnType<typeof findConfluences>; confluenceMinutes: number; recentWallets: WalletRow[]; onTab(value: Tab): void; onCopy(value: string, message?: string): void; onFavorite(address: string): void; onSelect(address: string): void; onInspect(wallet: WalletRow): void; onRemember(address: string): void; onConfluence(coin: string, direction: string): void; onConfluenceMinutes(value: number): void }) {
  const t = (ru: string, en: string) => text(p.preferences.language, ru, en);
  return <>
    <div className="mb-4 flex flex-wrap items-end justify-between gap-3">
      <div><h1 className="text-xl font-semibold tracking-[-.025em] sm:text-2xl">{t("Радар сильных трейдеров", "Top trader radar")}</h1><p className="mt-1 text-xs text-[var(--muted)]">{p.initialData.wallets.length} {t("отобраны из", "selected from")} {p.initialData.sourceCount.toLocaleString(p.preferences.language === "en" ? "en-US" : "ru-RU")} {t("публичных аккаунтов", "public accounts")}</p></div>
      <div className="flex gap-2"><button onClick={() => p.onTab("pulse")} className="compact-action border border-[var(--line)]"><Icon name="pulse" size={14}/>{t("Live-лента", "Live feed")}</button><button onClick={() => p.onTab("wallets")} className="compact-action border border-[#5ee3dc44] text-[var(--cyan)]">{t("Открыть рейтинг", "Open ranking")}<Icon name="arrow" size={13}/></button></div>
    </div>
    <MarketStrip prices={p.prices} hidden={p.hiddenMarkets} onCopy={(coin, value) => p.onCopy(`${coin} ${price(value)}`, `${coin}: ${t("цена скопирована", "price copied")}`)}/>
    <section className="overview-summary mt-4 grid grid-cols-2 overflow-hidden rounded-[10px] border border-[var(--line)] bg-[var(--panel)] sm:grid-cols-3 xl:grid-cols-6"><MetricCard label={t("Капитал выборки", "Sample capital")} value={p.money(p.insights.accountValue)}/><MetricCard label="30D PnL" value={p.money(p.insights.monthPnl)} tone={p.insights.monthPnl >= 0 ? "gain" : "loss"}/><MetricCard label="24H PnL" value={p.money(p.insights.dayPnl)} tone={p.insights.dayPnl >= 0 ? "gain" : "loss"}/><MetricCard label={t("Медиана ROI", "Median ROI")} value={`${p.insights.medianRoi.toFixed(1)}%`}/><MetricCard label={t("В плюсе 24H", "Positive 24H")} value={`${p.insights.positiveToday}/${p.initialData.wallets.length}`}/><MetricCard label="Risk alerts" value={String(p.insights.riskFlags)} tone={p.insights.riskFlags ? "warn" : "gain"}/></section>
    <MarketMoversPanel movers={p.initialData.marketMovers}/>
    <div className="mt-4 grid gap-4 xl:grid-cols-[minmax(0,1fr)_340px]">
      <section className="surface min-w-0 overflow-hidden"><PanelHead title={t("Топ трейдеров", "Top traders")} note={`${p.initialData.wallets.length} ${t("проверяемых аккаунтов", "tracked accounts")}`} action={t("Открыть рейтинг", "Open ranking")} onAction={() => p.onTab("wallets")}/><TraderTable {...p} onFavorite={p.onFavorite}/></section>
      <aside className="space-y-4">
        <section className="overview-confluences surface overflow-hidden"><PanelHead title={t("Совпадения 2.0", "Confluences 2.0")} note={t("Независимые кошельки · качество · объём · точный разброс", "Independent wallets · quality · size · exact spread")}/><ConfluenceControls value={p.confluenceMinutes} exactWallets={p.initialData.tracked.length} onChange={p.onConfluenceMinutes}/>{p.confluences.length ? <div>{p.confluences.slice(0, 6).map((item) => { const market = marketIdentity(item.coin); return <button onClick={() => p.onConfluence(item.coin, item.direction)} key={`${item.coin}-${item.direction}`} className="flex w-full items-center gap-3 border-b border-[var(--line)] px-4 py-3 text-left last:border-0 hover:bg-white/[.025]"><span className={`side-badge ${item.direction === "LONG" ? "gain" : "loss"}`}>{item.direction}</span><div className="min-w-0 flex-1"><p className="text-sm font-semibold">{market.symbol} <span className="mono ml-1 text-[10px] font-normal text-[var(--muted)]">{p.money(item.totalNotional)} · score {item.score}</span></p><p suppressHydrationWarning className="mt-0.5 truncate text-[10px] text-[var(--muted)]">{item.entries.map((entry) => entry.walletName || short(entry.wallet)).join(" + ")} · {spanText(item.spanMs, p.preferences.language)}</p></div><span className="mono text-xs text-[var(--cyan)]">×{item.independentWallets}</span></button>; })}</div> : <Empty text={t("В выбранном окне нет подтверждённых совпадений.", "No confirmed confluences in this window.")}/>}</section>
        <section className="overview-recent surface overflow-hidden"><PanelHead title={t("Недавно просмотренные", "Recently viewed")} note={`${p.recentWallets.length} ${t("на этом устройстве", "on this device")}`}/>{p.recentWallets.length ? <MiniWalletList wallets={p.recentWallets} money={p.money} onRemember={p.onRemember}/> : <Empty text={t("Открой профиль трейдера — он появится здесь.", "Open a trader profile to see it here.")}/>}</section>
        <section className="overview-latest surface overflow-hidden"><PanelHead title={t("Последняя активность", "Latest activity")} note={`${p.initialData.tradeCoverage} wallets live · ${p.initialData.tracked.length} exact`} action={t("Вся лента", "Full feed")} onAction={() => p.onTab("pulse")}/><FillFeed compact fills={p.fills.slice(0, 7)} favorites={p.favorites} money={p.money} time={p.time} onFavorite={p.onFavorite} onRemember={p.onRemember} onCopy={p.onCopy}/></section>
      </aside>
    </div>
  </>;
}

function WalletsView(p: { wallets: WalletRow[]; all: WalletRow[]; insights: ReturnType<typeof walletInsights>; filters: WalletFilters; setFilters(value: WalletFilters): void; sort: WalletSort; setSort(value: WalletSort): void; direction: "asc" | "desc"; setDirection(value: "asc" | "desc"): void; filtersOpen: boolean; setFiltersOpen(value: boolean): void; activeFilterCount: number; presets: Preset[]; onSavePreset(): void; onApplyPreset(preset: Preset): void; onRemovePreset(id: string): void; onReset(): void; page: number; pages: number; pageSize: number; setPage(value: number): void; setPageSize(value: number): void; favorites: Set<string>; selected: Set<string>; notes: Record<string, string>; tags: Record<string, string>; density: "compact" | "comfortable"; privacy: boolean; money(value: number): string; onFavorite(address: string): void; onSelect(address: string): void; onInspect(wallet: WalletRow): void; onRemember(address: string): void; onCopy(value: string, message?: string): void }) { const t = useT(); return <section className="surface overflow-hidden"><div className="flex flex-col gap-3 border-b border-[var(--line)] p-3 sm:p-4"><div className="flex flex-wrap items-end gap-3"><div className="mr-auto"><h1 className="text-lg font-semibold">{t("Рейтинг трейдеров", "Trader ranking")}</h1><p className="mt-1 text-[11px] text-[var(--muted)]">{t("Целостные аккаунты: капитал, стабильность, результат и активность", "Complete accounts: capital, consistency, performance and activity")}</p></div><button onClick={() => download("dc-pulse-wallets.csv", walletsCsv(p.all))} className="compact-action border border-[var(--line)]"><Icon name="download" size={14}/>CSV</button><button onClick={() => p.onCopy(p.all.map((wallet) => wallet.address).join("\n"), t("Адреса скопированы", "Addresses copied"))} className="compact-action border border-[var(--line)]"><Icon name="copy" size={14}/>{t("Адреса", "Addresses")}</button></div><div className="grid gap-2 lg:grid-cols-[minmax(220px,1fr)_150px_110px_auto_auto]"><label className="control-field flex min-w-0 items-center gap-2"><Icon name="search" size={15}/><input id="wallet-search" value={p.filters.query} onChange={(event) => p.setFilters({ ...p.filters, query: event.target.value })} placeholder={t("Адрес или имя  /", "Address or name  /")} className="min-w-0 flex-1 bg-transparent outline-none"/></label><select value={p.sort} onChange={(event) => p.setSort(event.target.value as WalletSort)} className="control-field" aria-label={t("Сортировка", "Sort")}><option value="rank">{t("Качество", "Quality")}</option><option value="monthPnl">30D PnL</option><option value="monthRoi">30D ROI</option><option value="dayPnl">24H PnL</option><option value="accountValue">Account</option><option value="dayVolume">24H volume</option></select><button onClick={() => p.setDirection(p.direction === "asc" ? "desc" : "asc")} className="control-field flex items-center justify-between">{p.direction === "asc" ? t("По возр.", "Ascending") : t("По убыв.", "Descending")}<span className="mono">{p.direction === "asc" ? "↑" : "↓"}</span></button><button onClick={() => p.setFiltersOpen(!p.filtersOpen)} className={`control-field flex items-center justify-center gap-2 ${p.filtersOpen || p.activeFilterCount ? "border-[#5ee3dc55] text-[var(--cyan)]" : ""}`}><Icon name="filter" size={14}/>{t("Фильтры", "Filters")}{p.activeFilterCount ? <b className="filter-count">{p.activeFilterCount}</b> : null}</button><button onClick={p.onReset} className="control-field text-[var(--muted)]">{t("Сбросить", "Reset")}</button></div></div>{p.filtersOpen && <WalletFilterPanel filters={p.filters} setFilters={p.setFilters} presets={p.presets} onSavePreset={p.onSavePreset} onApplyPreset={p.onApplyPreset} onRemovePreset={p.onRemovePreset}/>}<div className="flex flex-wrap items-center gap-x-4 gap-y-2 border-b border-[var(--line)] bg-white/[.012] px-4 py-2 text-[10px] text-[var(--muted)]"><span><b className="mono text-white">{p.all.length}</b> {t("найдено", "found")}</span><span>{t("Капитал", "Capital")} <b className="mono text-white">{p.money(p.insights.accountValue)}</b></span><span>30D <b className={`mono ${p.insights.monthPnl >= 0 ? "text-[var(--cyan)]" : "text-[var(--loss)]"}`}>{p.money(p.insights.monthPnl)}</b></span><span className="ml-auto">{t("Выбрано", "Selected")} <b className="mono text-white">{p.selected.size}/4</b></span></div>{p.wallets.length ? <TraderTable {...p} onFavorite={p.onFavorite}/> : <EmptyState title={t("Ничего не найдено", "Nothing found")} text={t("Ослабь фильтры или сбрось поиск.", "Loosen filters or reset the search.")} action={t("Сбросить фильтры", "Reset filters")} onAction={p.onReset}/>}<Pagination page={p.page} pages={p.pages} pageSize={p.pageSize} total={p.all.length} onPage={p.setPage} onPageSize={p.setPageSize}/></section>; }

function PulseView(p: { fills: PulseFill[]; filters: ActivityFilters; setFilters(value: ActivityFilters): void; coins: string[]; stats: { exact: number; public: number; wallets: number; notional: number }; live: boolean; limit: number; setLimit(value: number): void; favorites: Set<string>; money(value: number): string; time(value: number): string; onFavorite(address: string): void; onRemember(address: string): void; onCopy(value: string, message?: string): void; confluences: ReturnType<typeof findConfluences>; confluenceMinutes: number; exactWallets: number; onConfluenceMinutes(value: number): void; coinFlow: CoinFlow[] }) {
  const language = useContext(LanguageContext); const t = useT();
  return <div className="space-y-4">
    <section className="surface overflow-hidden">
      <PanelHead title={t("Живая активность", "Live activity")} note={p.live ? t("Поток подключён — новые исполнения появляются обычно быстрее 3 секунд", "Stream connected — new fills usually appear within 3 seconds") : t("Переподключаем поток; сохранённые события остаются доступны", "Reconnecting the stream; saved events remain available")} action={t("Экспорт CSV", "Export CSV")} onAction={() => download("deep-current-activity.csv", fillsCsv(p.fills))}/>
      <div className="border-b border-[var(--line)] bg-white/[.015] px-4 py-2 text-[10px] leading-relaxed text-[var(--muted)]"><b className="text-white">{t("ТОЧНО", "EXACT")}</b> — {t("Open/Add/Reduce/Close подтверждены историей позиции.", "Open/Add/Reduce/Close are confirmed from position history.")} <b className="ml-2 text-white">{t("ИСПОЛНЕНИЕ", "FILL")}</b> — {t("подтверждён BUY/SELL, но открытие или закрытие определить нельзя.", "BUY/SELL is confirmed, but open versus close cannot be determined.")}</div>
      <div className="grid grid-cols-2 border-b border-[var(--line)] sm:grid-cols-4"><Summary label={t("Точные изменения", "Exact changes")} value={String(p.stats.exact)} accent/><Summary label={t("Публичные исполнения", "Public fills")} value={String(p.stats.public)}/><Summary label={t("Кошельки", "Wallets")} value={String(p.stats.wallets)}/><Summary label={t("Объём, USD", "Notional, USD")} value={p.money(p.stats.notional)}/></div>
      <ActivityToolbar filters={p.filters} coins={p.coins} setFilters={p.setFilters}/>
      {p.fills.length ? <FillFeed fills={p.fills.slice(0, p.limit)} favorites={p.favorites} money={p.money} time={p.time} onFavorite={p.onFavorite} onRemember={p.onRemember} onCopy={p.onCopy}/> : <EmptyState title={t("Сделок нет", "No trades")} text={t("Попробуй другой рынок, сумму, источник или направление.", "Try another market, amount, source or direction.")} action={t("Сбросить фильтры", "Reset filters")} onAction={() => p.setFilters(defaultActivityFilters)}/>}
      {p.fills.length > p.limit && <div className="border-t border-[var(--line)] p-3 text-center"><button onClick={() => p.setLimit(p.limit + 50)} className="compact-action border border-[var(--line)]">{t("Показать ещё 50", "Show 50 more")}</button></div>}
    </section>
    <CoinFlowPanel rows={p.coinFlow}/>
    <section className="surface overflow-hidden"><PanelHead title={t("Совпадения 2.0", "Confluences 2.0")} note={t("Связанные адреса считаются одним источником", "Related addresses count as one source")}/><ConfluenceControls value={p.confluenceMinutes} exactWallets={p.exactWallets} onChange={p.onConfluenceMinutes}/>{p.confluences.length ? <div className="grid sm:grid-cols-2 xl:grid-cols-3">{p.confluences.map((item) => { const market = marketIdentity(item.coin); return <button key={`${item.coin}-${item.direction}`} onClick={() => p.setFilters({ ...defaultActivityFilters, coin: item.coin, action: item.direction === "LONG" ? "long" : "short" })} className="border-b border-r border-[var(--line)] px-4 py-3 text-left hover:bg-white/[.025]"><div className="flex items-center gap-3"><span className={`side-badge ${item.direction === "LONG" ? "gain" : "loss"}`}>{item.direction}</span><p className="flex-1 font-semibold">{market.symbol}</p><span className="mono text-[var(--cyan)]">{item.score}/100</span></div><p className="mono mt-2 text-[10px] text-white">{p.money(item.totalNotional)} · {spanText(item.spanMs, language)} · {item.independentWallets} independent</p><div className="mt-2 space-y-1">{item.entries.slice(0, 4).map((entry) => <p key={entry.wallet} className="flex justify-between gap-3 text-[10px] text-[var(--muted)]"><span className="truncate">{entry.walletName || short(entry.wallet)} · Q{Math.round(entry.quality)}</span><time className="mono shrink-0" suppressHydrationWarning>{p.time(entry.time)}</time></p>)}</div>{item.relatedWallets ? <p className="mt-2 text-[9px] text-[var(--warn)]">{item.relatedWallets} related address ignored</p> : null}</button>; })}</div> : <Empty text={t("В выбранном окне нет подтверждённых совпадений.", "No confirmed confluences in this window.")}/>}</section>
  </div>;
}

const spanText = (milliseconds: number, language: UserLanguage) => {
  const minutes = Math.max(1, Math.ceil(milliseconds / 60_000));
  return language === "en" ? `within ${minutes}m` : `интервал ${minutes} мин`;
};

function ConfluenceControls({ value, exactWallets, onChange }: { value: number; exactWallets: number; onChange(value: number): void }) {
  const t = useT();
  return <div className="flex items-center justify-between gap-3 border-b border-[var(--line)] bg-white/[.012] px-4 py-2 text-[10px] text-[var(--muted)]"><span>{t("Точный охват", "Exact coverage")}: <b className="mono text-white">{exactWallets}</b> {t("кошельков", "wallets")}</span><label className="flex items-center gap-2"><span>{t("Окно", "Window")}</span><select value={value} onChange={(event) => onChange(Number(event.target.value))} className="h-8 rounded-md border border-[var(--line)] bg-[#080808] px-2 text-xs text-white" aria-label={t("Окно совпадения", "Confluence window")}><option value="5">5 мин</option><option value="15">15 мин</option><option value="30">30 мин</option><option value="60">1 час</option><option value="120">2 часа</option><option value="240">4 часа</option><option value="1440">24 часа</option></select></label></div>;
}

function FavoritesView(p: { wallets: WalletRow[]; favorites: Set<string>; selected: Set<string>; notes: Record<string, string>; tags: Record<string, string>; density: "compact" | "comfortable"; privacy: boolean; money(value: number): string; onFavorite(address: string): void; onSelect(address: string): void; onInspect(wallet: WalletRow): void; onRemember(address: string): void; onOpen(): void }) { const insights = walletInsights(p.wallets); const t = useT(); return <section className="surface overflow-hidden"><PanelHead title={t("Избранные трейдеры", "Favorite traders")} note={`${p.wallets.length} ${t("сохранено локально", "saved locally")}`} action={p.wallets.length ? t("Экспорт CSV", "Export CSV") : undefined} onAction={() => download("dc-pulse-favorites.csv", walletsCsv(p.wallets))}/>{p.wallets.length ? <><div className="grid grid-cols-2 border-b border-[var(--line)] sm:grid-cols-4"><Summary label="Account value" value={p.money(insights.accountValue)}/><Summary label="30D PnL" value={p.money(insights.monthPnl)} accent/><Summary label={t("В плюсе 24H", "Positive 24H")} value={String(insights.positiveToday)}/><Summary label={t("С заметками", "With notes")} value={String(p.wallets.filter((wallet) => p.notes[wallet.address]).length)}/></div><TraderTable {...p} onFavorite={p.onFavorite}/></> : <EmptyState title={t("Избранное пусто", "No favorites yet")} text={t("Нажми звезду у трейдера — профиль останется под рукой.", "Star a trader to keep their profile close.")} action={t("Открыть рейтинг", "Open ranking")} onAction={p.onOpen}/>}</section>; }

function AccountView(p: { user: SessionState["user"] | null; isAdmin: boolean; chatLinked: boolean; favoritesCount: number; notificationSettings: NotificationSettings; preferences: UserPreferences; onSettings(section?: SettingsSection): void; onTab(value: Tab): void; onLanguage(value: UserLanguage): void }) {
  const t = useT(); const displayName = p.user ? [p.user.firstName, p.user.lastName].filter(Boolean).join(" ") || p.user.username || t("Пользователь Telegram", "Telegram user") : t("Локальный профиль", "Local profile");
  const initials = displayName.split(/\s+/).map((part) => part[0]).join("").slice(0, 2).toUpperCase();
  return <div className="mx-auto grid max-w-4xl gap-4 lg:grid-cols-[minmax(0,1fr)_320px]"><section className="surface overflow-hidden"><div className="flex items-center gap-4 border-b border-[var(--line)] p-5"><span className="mono flex size-12 shrink-0 items-center justify-center rounded-full border border-[#5ee3dc44] bg-[#5ee3dc0d] text-sm text-[var(--cyan)]">{initials}</span><div className="min-w-0"><h1 className="truncate text-lg font-semibold">{displayName}</h1><p className="mt-1 truncate text-[11px] text-[var(--muted)]">{p.user?.username ? `@${p.user.username}` : t("Настройки хранятся на этом устройстве", "Settings are stored on this device")}</p></div>{p.isAdmin && <span className="quality-badge quality-elite ml-auto">ADMIN</span>}</div><div className="grid grid-cols-2 border-b border-[var(--line)] sm:grid-cols-4"><Summary label={t("Избранные", "Favorites")} value={String(p.favoritesCount)} accent/><Summary label="Telegram" value={p.chatLinked ? t("Подключён", "Connected") : t("Не подключён", "Not linked")}/><Summary label={t("Уведомления", "Notifications")} value={p.notificationSettings.enabled ? t("Включены", "Enabled") : t("Выключены", "Disabled")}/><Summary label={t("Язык", "Language")} value={p.preferences.language.toUpperCase()}/></div><div className="divide-y divide-[var(--line)]"><button onClick={() => p.onSettings()} className="account-row"><span><b>{t("Личные настройки", "Personal settings")}</b><small>{t("56 параметров интерфейса, рейтинга и ленты", "56 interface, ranking and feed preferences")}</small></span><Icon name="settings" size={17}/></button><button onClick={() => p.onTab("favorites")} className="account-row"><span><b>{t("Избранные трейдеры", "Favorite traders")}</b><small>{t("Открыть сохранённые кошельки", "Open saved wallets")}</small></span><Icon name="star" size={17}/></button><button onClick={() => p.onSettings("notifications")} className="account-row"><span><b>{t("Telegram-уведомления", "Telegram notifications")}</b><small>{t("Открытия, закрытия, фильтры и тихие часы", "Open, close, filters and quiet hours")}</small></span><Icon name="pulse" size={17}/></button>{p.isAdmin && <button onClick={() => p.onTab("admin")} className="account-row"><span><b>{t("Админ-панель", "Admin panel")}</b><small>{t("Пользователи, сбор данных и состояние системы", "Users, data collection and system status")}</small></span><Icon name="shield" size={17}/></button>}</div></section><aside className="surface self-start overflow-hidden"><PanelHead title={t("Язык приложения", "App language")} note={t("Меняется сразу на всех экранах", "Changes instantly across every screen")}/><div className="grid grid-cols-2 gap-2 p-4"><button onClick={() => p.onLanguage("ru")} className={`control-field text-center ${p.preferences.language === "ru" ? "border-[#5ee3dc55] text-[var(--cyan)]" : ""}`}>Русский</button><button onClick={() => p.onLanguage("en")} className={`control-field text-center ${p.preferences.language === "en" ? "border-[#5ee3dc55] text-[var(--cyan)]" : ""}`}>English</button></div><div className="border-t border-[var(--line)] p-4"><p className="text-[10px] leading-relaxed text-[var(--muted)]">{p.chatLinked ? t("Профиль синхронизирован с вашим Telegram-аккаунтом.", "This profile is synced with your Telegram account.") : t("Откройте мини-приложение через Telegram, чтобы синхронизировать профиль и уведомления.", "Open the Mini App through Telegram to sync your profile and notifications.")}</p></div></aside></div>;
}

function Brand() { return <span className="flex shrink-0 items-center gap-2.5 text-left"><span className="relative size-9 overflow-hidden rounded-[9px] border border-white/[.08] bg-[#02060c]"><Image src="/dc-pulse-mark.png" fill sizes="36px" alt="" className="object-cover" priority/></span><span className="block text-sm font-semibold leading-none">Deep Current</span></span>; }
function ActivityTicker({ items, paused, onToggle, money, time, onRemember }: { items: TapeItem[]; paused: boolean; onToggle(): void; money(value: number): string; time(value: number): string; onRemember(address: string): void }) { const t = useT(); return <section className="border-b border-[var(--line)] bg-[#050505]"><div className="mx-auto flex h-11 max-w-[1800px] items-stretch"><button onClick={onToggle} className="ticker-toggle" aria-label={paused ? t("Запустить ленту", "Start ticker") : t("Приостановить ленту", "Pause ticker")}>{paused ? "▶" : "Ⅱ"}</button><div className="flex min-w-0 flex-1 items-stretch overflow-x-auto thin-scrollbar">{items.length ? items.slice(0, 24).map((item) => { const market = marketIdentity(item.coin); return <Link onClick={() => onRemember(item.wallet)} href={`/wallet/${item.wallet}`} key={item.id} title={`${market.venue} · ${item.walletName}`} className="flex shrink-0 items-center gap-2 border-r border-[var(--line)] px-3 text-[10px] hover:bg-white/[.025]"><span className="mono flex size-5 items-center justify-center rounded-full border border-white/[.1] bg-white/[.035] text-[8px]">{market.symbol.slice(0, 2)}</span><b className="text-xs">{market.symbol}</b><span className={`side-badge !h-[19px] !min-w-0 px-2 ${item.kind === "gain" ? "gain" : item.kind === "loss" ? "loss" : ""}`}>{item.action}</span><span className="mono text-[var(--muted)]">{short(item.wallet)}</span><strong className="mono text-[11px]">{money(item.notional)}</strong><span className="mono text-[var(--muted)]">@ {price(item.price)}</span><time suppressHydrationWarning className="mono text-[var(--muted)]">{time(item.time)}</time></Link>; }) : <p className="flex items-center px-4 text-[10px] text-[var(--muted)]">{t("Ожидаем крупную сделку…", "Waiting for a large trade…")}</p>}</div></div></section>; }
function MarketStrip({ prices, hidden, onCopy }: { prices: Record<string, number>; hidden: Set<string>; onCopy(coin: string, value: number): void }) { const visible = Object.entries(prices).filter(([coin]) => !hidden.has(coin)); const t = useT(); return <section className="overview-market-strip surface flex min-h-14 items-stretch overflow-x-auto thin-scrollbar">{visible.length ? visible.map(([coin, value], index) => <button onClick={() => onCopy(coin, value)} key={coin} className={`flex min-w-[150px] flex-1 items-center justify-between gap-4 px-4 py-2 text-left hover:bg-white/[.025] ${index ? "border-l border-[var(--line)]" : ""}`}><span><span className="block text-[10px] text-[var(--muted)]">{coin} / USD</span><span className="mono mt-1 block text-sm">{value ? price(value) : "—"}</span></span><span className="size-1.5 rounded-full bg-[var(--cyan)]"/></button>) : <p className="flex items-center px-4 text-xs text-[var(--muted)]">{t("Все рынки скрыты.", "All markets are hidden.")}</p>}</section>; }

function TraderTable({ wallets, favorites, selected, notes, tags, density, privacy, money, onFavorite, onSelect, onInspect, onRemember }: { wallets: WalletRow[]; favorites: Set<string>; selected: Set<string>; notes: Record<string, string>; tags: Record<string, string>; density: "compact" | "comfortable"; privacy: boolean; money(value: number): string; onFavorite(address: string): void; onSelect(address: string): void; onInspect(wallet: WalletRow): void; onRemember(address: string): void }) { const language = useContext(LanguageContext); const t = (ru: string, en: string) => text(language, ru, en); return <div><div className="wallet-table-head hidden grid-cols-[42px_minmax(190px,1fr)_120px_110px_120px_90px_120px_80px] items-center border-b border-[var(--line)] px-3 py-2 text-[9px] font-semibold uppercase tracking-[.08em] text-[var(--muted)] lg:grid"><span>#</span><span>{t("Трейдер", "Trader")}</span><span className="wallet-account-column text-right">Account</span><span className="wallet-day-pnl-column text-right">24H PnL</span><span className="wallet-month-pnl-column text-right">30D PnL</span><span className="wallet-roi-column text-right">30D ROI</span><span className="wallet-volume-column text-right">24H volume</span><span/></div><div className="wallet-rows divide-y divide-[var(--line)]">{wallets.map((wallet) => { const risks = walletRiskFlags(wallet); return <article key={wallet.address} className={`wallet-row group relative grid grid-cols-2 gap-x-3 px-3 hover:bg-white/[.025] sm:grid-cols-5 lg:grid-cols-[42px_minmax(190px,1fr)_120px_110px_120px_90px_120px_80px] lg:items-center ${density === "comfortable" ? "py-4 lg:py-3.5" : "py-3 lg:py-2.5"} ${selected.has(wallet.address) ? "bg-[#5ee3dc08]" : ""}`}><button onClick={() => onSelect(wallet.address)} className={`mono hidden size-7 items-center justify-center rounded-md border text-[10px] lg:flex ${selected.has(wallet.address) ? "border-[#5ee3dc66] bg-[#5ee3dc12] text-[var(--cyan)]" : "border-transparent text-[var(--muted)]"}`}>{selected.has(wallet.address) ? "✓" : String(wallet.rank).padStart(2, "0")}</button><div className="col-span-2 flex min-w-0 items-center gap-3 sm:col-span-5 lg:col-span-1"><button onClick={() => onSelect(wallet.address)} className={`mono flex size-8 shrink-0 items-center justify-center rounded-full border text-[10px] lg:hidden ${selected.has(wallet.address) ? "border-[#5ee3dc66] text-[var(--cyan)]" : "border-white/[.08]"}`}>{selected.has(wallet.address) ? "✓" : wallet.rank}</button><Link onClick={() => onRemember(wallet.address)} href={`/wallet/${wallet.address}`} className="min-w-0 flex-1"><div className="flex items-center gap-2"><p className="truncate text-sm font-medium group-hover:text-[var(--cyan)]">{wallet.name}</p><span className={`wallet-quality quality-badge quality-${qualityBand(wallet).toLowerCase()}`}>{qualityBand(wallet)}</span>{risks.length ? <span title={risks.map((flag) => riskText(language, flag)).join(" · ")} className="wallet-risk risk-dot">!</span> : null}</div><p className="wallet-address mono mt-0.5 text-[10px] text-[var(--muted)]">{privacy ? "0x••••••••••" : short(wallet.address)}{tags[wallet.address] ? ` · ${tags[wallet.address]}` : ""}{notes[wallet.address] ? " · 📝" : ""}</p></Link></div><Cell className="wallet-account-column" label="Account" value={money(wallet.accountValue)}/><Cell className="wallet-day-pnl-column" label="24H PnL" value={<Pnl value={wallet.dayPnl} money={money}/>}/><Cell className="wallet-month-pnl-column" label="30D PnL" value={<Pnl value={wallet.monthPnl} money={money}/>}/><Cell className="wallet-roi-column" label="30D ROI" value={<Pnl value={wallet.monthRoi} suffix="%" money={money}/>}/><Cell className="wallet-volume-column" label="24H volume" value={money(wallet.dayVolume)}/><div className="absolute right-3 top-3 flex gap-1 lg:static lg:justify-end"><button onClick={() => onInspect(wallet)} className="icon-button" aria-label={t("Карточка трейдера", "Trader card")}><Icon name="command" size={14}/></button><button onClick={() => onFavorite(wallet.address)} className="icon-button" aria-label={t("Избранное", "Favorite")}><Icon name="star" size={15} filled={favorites.has(wallet.address)}/></button></div></article>; })}</div></div>; }

function WalletFilterPanel({ filters, setFilters, presets, onSavePreset, onApplyPreset, onRemovePreset }: { filters: WalletFilters; setFilters(value: WalletFilters): void; presets: Preset[]; onSavePreset(): void; onApplyPreset(preset: Preset): void; onRemovePreset(id: string): void }) { const t = useT(); return <div className="border-b border-[var(--line)] bg-[#080808] p-4"><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><FilterSelect label={t("Результат 24H", "24H performance")} value={filters.performance} onChange={(value) => setFilters({ ...filters, performance: value as WalletFilters["performance"] })} options={[["all", t("Все", "All")], ["winners", t("Только в плюсе", "Winners only")], ["losers", t("Только в минусе", "Losers only")]]}/><NumberFilter label={t("Мин. капитал, USD", "Min. capital, USD")} value={filters.minAccount} onChange={(value) => setFilters({ ...filters, minAccount: value })}/><NumberFilter label="Min. 30D PnL, USD" value={filters.minMonthPnl} onChange={(value) => setFilters({ ...filters, minMonthPnl: value })}/><NumberFilter label="Min. 30D ROI, %" value={filters.minRoi} onChange={(value) => setFilters({ ...filters, minRoi: value })}/><NumberFilter label={t("Мин. торговый объём 24H, USD", "Min. 24H trading volume, USD")} value={filters.minVolume} onChange={(value) => setFilters({ ...filters, minVolume: value })}/><Toggle label={t("Только с именем", "Named only")} checked={filters.namedOnly} onChange={(value) => setFilters({ ...filters, namedOnly: value })}/><Toggle label={t("Только избранные", "Favorites only")} checked={filters.favoritesOnly} onChange={(value) => setFilters({ ...filters, favoritesOnly: value })}/><Toggle label={t("Без risk-флагов", "No risk flags")} checked={filters.riskFreeOnly} onChange={(value) => setFilters({ ...filters, riskFreeOnly: value })}/></div><div className="mt-4 flex flex-wrap items-center gap-2 border-t border-[var(--line)] pt-3"><button onClick={onSavePreset} className="compact-action border border-[var(--line)]">+ {t("Сохранить набор", "Save preset")}</button>{presets.map((preset) => <span key={preset.id} className="preset-chip"><button onClick={() => onApplyPreset(preset)}>{preset.name}</button><button onClick={() => onRemovePreset(preset.id)} aria-label={`${t("Удалить", "Delete")} ${preset.name}`}>×</button></span>)}</div></div>; }
function ActivityToolbar({ filters, coins, setFilters }: { filters: ActivityFilters; coins: string[]; setFilters(value: ActivityFilters): void }) {
  const t = useT();
  return <div className="grid gap-2 border-b border-[var(--line)] p-3 sm:grid-cols-2 xl:grid-cols-[minmax(200px,1fr)_150px_140px_150px_160px_150px_auto]">
    <label className="control-field flex items-center gap-2" aria-label={t("Поиск", "Search")}><Icon name="search" size={14}/><input value={filters.query} onChange={(event) => setFilters({ ...filters, query: event.target.value })} placeholder={t("Монета, имя или адрес", "Coin, name or address")} className="min-w-0 flex-1 bg-transparent outline-none"/></label>
    <label className="filter-control"><span>{t("Рынок", "Market")}</span><select value={filters.coin} onChange={(event) => setFilters({ ...filters, coin: event.target.value })}><option value="all">{t("Все", "All")}</option>{coins.map((coin) => <option key={coin}>{coin}</option>)}</select></label>
    <label className="filter-control"><span>{t("Действие", "Action")}</span><select value={filters.action} onChange={(event) => setFilters({ ...filters, action: event.target.value as ActivityFilters["action"] })}><option value="all">{t("Все", "All")}</option><option value="long">Long / Buy</option><option value="short">Short / Sell</option><option value="reduced">Reduce / Close</option></select></label>
    <label className="filter-control"><span>{t("Источник", "Source")}</span><select value={filters.source} onChange={(event) => setFilters({ ...filters, source: event.target.value as ActivityFilters["source"] })}><option value="all">{t("Все", "All")}</option><option value="exact">{t("Точные позиции", "Exact positions")}</option><option value="market">{t("Публичные исполнения", "Public fills")}</option></select></label>
    <label className="filter-control"><span>{t("Сумма сделки, USD", "Trade value, USD")}</span><select value={filters.minNotional} onChange={(event) => setFilters({ ...filters, minNotional: Number(event.target.value) })}><option value="0">{t("Любая", "Any")}</option><option value="5000">≥ $5K</option><option value="25000">≥ $25K</option><option value="100000">≥ $100K</option><option value="500000">≥ $500K</option></select></label>
    <label className="filter-control"><span>{t("Порядок", "Order")}</span><select value={filters.sort} onChange={(event) => setFilters({ ...filters, sort: event.target.value as ActivityFilters["sort"] })}><option value="newest">{t("Сначала новые", "Newest first")}</option><option value="largest">{t("Сначала крупные", "Largest first")}</option></select></label>
    <Toggle label={t("Избранные", "Favorites")} checked={filters.favoritesOnly} onChange={(value) => setFilters({ ...filters, favoritesOnly: value })}/>
  </div>;
}

function FillFeed({ fills, favorites, money, time, onFavorite, onRemember, onCopy, compact = false }: { fills: PulseFill[]; favorites: Set<string>; money(value: number): string; time(value: number): string; onFavorite(address: string): void; onRemember(address: string): void; onCopy(value: string, message?: string): void; compact?: boolean }) {
  const t = useT();
  if (!fills.length) return <Empty text={t("Новые сделки появятся здесь автоматически.", "New trades will appear here automatically.")}/>;
  return <div className="divide-y divide-[var(--line)]">{fills.map((fill, index) => {
    const action = activityKind(fill); const market = marketIdentity(fill.coin); const notional = Math.abs(Number(fill.sz) * Number(fill.px));
    const before = Number(fill.startPosition); const after = before + Number(fill.sz) * (fill.side === "B" ? 1 : -1);
    return <article key={`${fill.hash}-${fill.wallet}-${index}`} className="grid grid-cols-[auto_minmax(0,1fr)_auto] items-start gap-3 px-4 py-3 hover:bg-white/[.025]">
      <span className={`side-badge mt-0.5 ${action.kind === "neutral" ? "" : action.kind}`}>{action.label}</span>
      <div className="min-w-0">
        <div className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1"><Link href={`/coin/${encodeURIComponent(fill.coin)}`} className="text-sm font-semibold hover:text-[var(--cyan)]">{market.symbol}</Link><span className="rounded border border-white/[.08] px-1.5 py-0.5 text-[8px] text-[var(--muted)]">{market.type}</span><span className={`rounded px-1.5 py-0.5 text-[8px] font-semibold ${action.exact ? "bg-[#5ee3dc16] text-[var(--cyan)]" : "bg-white/[.06] text-[var(--muted)]"}`}>{action.exact ? t("ТОЧНО", "EXACT") : t("ИСПОЛНЕНИЕ", "FILL")}</span><Link onClick={() => onRemember(fill.wallet)} href={`/wallet/${fill.wallet}`} className="truncate text-[11px] text-[var(--muted)] hover:text-white">{fill.walletName} · {market.venue}</Link></div>
        <p className="mono mt-1 text-[11px] text-white">{money(notional)} <span className="text-[var(--muted)]">· {Number(fill.sz).toLocaleString("en-US", { maximumFractionDigits: 6 })} {market.symbol} @ {price(Number(fill.px))} · <time suppressHydrationWarning title={new Date(fill.time).toISOString()}>{time(fill.time)}</time></span></p>
        {!compact && <p className="mt-1 text-[10px] leading-relaxed text-[var(--muted)]">{action.exact && Number.isFinite(before) ? `${t("Позиция после сделки", "Position after fill")}: ${before.toLocaleString("en-US", { maximumFractionDigits: 5 })} → ${after.toLocaleString("en-US", { maximumFractionDigits: 5 })}` : t("Подтверждённая сделка; Open/Close неизвестен без истории позиции", "Confirmed fill; Open/Close is unknown without position history")}</p>}
      </div>
      <div className="flex items-center gap-1"><button onClick={() => onCopy(`${fill.wallet} ${fill.coin} ${action.label} ${money(notional)} @ ${price(Number(fill.px))}`, t("Событие скопировано", "Event copied"))} className="icon-button" aria-label={t("Копировать событие", "Copy event")}><Icon name="copy" size={13}/></button><button onClick={() => onFavorite(fill.wallet)} className="icon-button" aria-label={t("Избранное", "Favorite")}><Icon name="star" size={13} filled={favorites.has(fill.wallet)}/></button></div>
    </article>;
  })}</div>;
}

function MarketMoversPanel({ movers }: { movers: { gainers: MarketMover[]; losers: MarketMover[] } }) {
  const t = useT();
  const list = (rows: MarketMover[], gain: boolean) => rows.length ? <div className="max-h-[340px] divide-y divide-[var(--line)] overflow-y-auto thin-scrollbar">{rows.map((row, index) => <Link prefetch={false} aria-label={`${row.symbol}: ${t("показать Long и Short наших трейдеров", "show our traders' Long and Short positions")}`} href={`/coin/${encodeURIComponent(row.symbol)}`} key={`${row.exchange}-${row.symbol}`} className="grid min-h-12 grid-cols-[28px_minmax(0,1fr)_80px_94px] items-center gap-2 px-3 py-2 text-xs transition-colors hover:bg-white/[.035] focus-visible:bg-white/[.05]"><span className="mono text-[10px] text-[var(--muted)]">{String(index + 1).padStart(2, "0")}</span><span className="min-w-0"><b>{row.symbol}</b><small className="ml-2 text-[10px] text-[var(--muted)]">{row.exchange}</small><span className="mono mt-0.5 block truncate text-[10px] text-[var(--muted)]">{row.wallets} {t("кош.", "wallets")} · <span className="text-[var(--cyan)]">{row.longWallets}L</span> · <span className="text-[var(--loss)]">{row.shortWallets}S</span></span></span><span className="mono text-right">{price(row.price)}</span><span className={`mono flex items-center justify-end gap-2 text-right font-semibold ${gain ? "text-[var(--cyan)]" : "text-[var(--loss)]"}`}>{row.change > 0 ? "+" : ""}{row.change.toFixed(2)}%<svg aria-hidden="true" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="m9 18 6-6-6-6"/></svg></span></Link>)}</div> : <Empty text={t("Сейчас нет свежих позиций наших трейдеров в монетах этого списка.", "No fresh tracked-trader positions in this list right now.")}/>;
  return <section className="mt-4 grid gap-4 lg:grid-cols-2"><div className="surface overflow-hidden"><PanelHead title={t("До 20 лидеров роста за 24 часа", "Up to 20 gainers · 24h")} note={t("Только монеты, где сейчас есть позиции наших трейдеров", "Only coins currently held by our tracked traders")}/>{list(movers.gainers, true)}</div><div className="surface overflow-hidden"><PanelHead title={t("До 20 лидеров падения за 24 часа", "Up to 20 losers · 24h")} note={t("Binance + Bybit spot · сопоставлено со свежими Long/Short", "Binance + Bybit spot · matched to fresh Long/Short positions")}/>{list(movers.losers, false)}</div></section>;
}

function CoinFlowPanel({ rows }: { rows: CoinFlow[] }) {
  const t = useT();
  return <section className="surface overflow-hidden"><PanelHead title={t("Какие монеты торгуют сильные трейдеры", "What top traders are trading")} note={t("Последние 24 часа · сохранённые события всех отслеживаемых кошельков", "Last 24 hours · persisted events from all tracked wallets")}/>{rows.length ? <div className="overflow-x-auto thin-scrollbar"><table className="w-full min-w-[720px] text-left"><thead><tr className="border-b border-[var(--line)] text-[9px] uppercase tracking-[.08em] text-[var(--muted)]"><ThCell>{t("Монета", "Coin")}</ThCell><ThCell align="right">{t("Трейдеры", "Traders")}</ThCell><ThCell align="right">{t("Сделки", "Fills")}</ThCell><ThCell align="right">{t("Купили, USD", "Bought, USD")}</ThCell><ThCell align="right">{t("Продали, USD", "Sold, USD")}</ThCell><ThCell align="right">{t("Поток", "Net flow")}</ThCell><ThCell align="right">Realized PnL</ThCell></tr></thead><tbody>{rows.map((row) => { const market = marketIdentity(row.coin); const net = row.buys - row.sells; return <tr key={row.coin} className="border-b border-[var(--line)] last:border-0"><TdCell><Link href={`/coin/${encodeURIComponent(row.coin)}`} className="font-semibold hover:text-[var(--cyan)]">{market.symbol}</Link><small className="ml-2 text-[9px] text-[var(--muted)]">{market.type}</small></TdCell><TdCell align="right">{row.wallets}</TdCell><TdCell align="right">{row.trades}</TdCell><TdCell align="right">{rawMoney(row.buys)}</TdCell><TdCell align="right">{rawMoney(row.sells)}</TdCell><TdCell align="right"><span className={net >= 0 ? "text-[var(--cyan)]" : "text-[var(--loss)]"}>{net >= 0 ? "+" : ""}{rawMoney(net)}</span></TdCell><TdCell align="right"><span className={row.realizedPnl >= 0 ? "text-[var(--cyan)]" : "text-[var(--loss)]"}>{row.realizedPnl >= 0 ? "+" : ""}{rawMoney(row.realizedPnl)}</span></TdCell></tr>; })}</tbody></table></div> : <Empty text={t("За последние 24 часа сохранённых торговых событий нет.", "No persisted trading events in the last 24 hours.")}/>}</section>;
}

function ThCell({ children, align = "left" }: { children: React.ReactNode; align?: "left" | "right" }) { return <th className={`px-4 py-2.5 font-medium ${align === "right" ? "text-right" : ""}`}>{children}</th>; }
function TdCell({ children, align = "left" }: { children: React.ReactNode; align?: "left" | "right" }) { return <td className={`mono px-4 py-2.5 text-xs ${align === "right" ? "text-right" : ""}`}>{children}</td>; }
function MiniWalletList({ wallets, money, onRemember }: { wallets: WalletRow[]; money(value: number): string; onRemember(address: string): void }) { return <div className="divide-y divide-[var(--line)]">{wallets.map((wallet) => <Link onClick={() => onRemember(wallet.address)} href={`/wallet/${wallet.address}`} key={wallet.address} className="flex items-center gap-3 px-4 py-2.5 hover:bg-white/[.025]"><span className="mono flex size-7 items-center justify-center rounded-full bg-white/[.035] text-[9px] text-[var(--cyan)]">{wallet.rank}</span><span className="min-w-0 flex-1"><span className="block truncate text-xs font-medium">{wallet.name}</span><span className="mono text-[9px] text-[var(--muted)]">{short(wallet.address)}</span></span><Pnl value={wallet.monthPnl} money={money}/></Link>)}</div>; }
function Pagination({ page, pages, pageSize, total, onPage, onPageSize }: { page: number; pages: number; pageSize: number; total: number; onPage(value: number): void; onPageSize(value: number): void }) { const t = useT(); return <div className="flex flex-wrap items-center gap-3 border-t border-[var(--line)] px-4 py-3 text-[10px] text-[var(--muted)]"><span>{total ? (page - 1) * pageSize + 1 : 0}–{Math.min(page * pageSize, total)} {t("из", "of")} {total}</span><label className="ml-auto flex items-center gap-2">{t("Строк", "Rows")}<select value={pageSize} onChange={(event) => onPageSize(Number(event.target.value))} className="control-field !min-h-8"><option value="10">10</option><option value="25">25</option><option value="50">50</option><option value="100">100</option></select></label><button aria-label={t("Предыдущая страница", "Previous page")} disabled={page <= 1} onClick={() => onPage(page - 1)} className="pagination-button">←</button><span className="mono text-white">{page}/{pages}</span><button aria-label={t("Следующая страница", "Next page")} disabled={page >= pages} onClick={() => onPage(page + 1)} className="pagination-button">→</button></div>; }

function SettingsDrawer(p: { initialSection: SettingsSection; notificationSettings: NotificationSettings; chatLinked: boolean; favoritesCount: number; notificationSaving: boolean; preferences: UserPreferences; prices: Record<string, number>; live: boolean; online: boolean; reconnects: number; lastMessage: number; time(value: number): string; onClose(): void; onNotificationSettings(value: NotificationSettings): void; onSaveNotifications(): void; onPreference(key: keyof UserPreferences, value: UserPreferences[keyof UserPreferences]): void }) {
  const [section, setSection] = useState<SettingsSection>(p.initialSection);
  const language = p.preferences.language; const t = (ru: string, en: string) => text(language, ru, en);
  const pref = <K extends keyof UserPreferences>(key: K, value: UserPreferences[K]) => p.onPreference(key, value);
  const update = (patch: Partial<NotificationSettings>) => p.onNotificationSettings({ ...p.notificationSettings, ...patch });
  const sections = [["general", t("Основные", "General")], ["interface", t("Интерфейс", "Interface")], ["ranking", t("Рейтинг", "Ranking")], ["feed", t("Лента", "Feed")], ["notifications", "Telegram"]] as const;
  const select = (label: string, key: keyof UserPreferences, options: string[][]) => <FilterSelect label={label} value={String(p.preferences[key])} onChange={(value) => pref(key, (typeof p.preferences[key] === "number" ? Number(value) : value) as never)} options={options}/>;
  return <Drawer title={t("Личные настройки", "Personal settings")} note={t("56 параметров интерфейса + 10 параметров уведомлений", "56 interface preferences + 10 notification settings")} onClose={p.onClose}>
    <div className="settings-tabs" role="tablist" onKeyDown={(event) => { if (!['ArrowLeft', 'ArrowRight'].includes(event.key)) return; event.preventDefault(); const tabs = [...event.currentTarget.querySelectorAll<HTMLButtonElement>('[role="tab"]')]; const current = tabs.indexOf(document.activeElement as HTMLButtonElement); const next = (current + (event.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length; tabs[next]?.focus(); tabs[next]?.click(); }}>{sections.map(([id, label]) => <button key={id} role="tab" tabIndex={section === id ? 0 : -1} aria-selected={section === id} onClick={() => setSection(id)} className={section === id ? "active" : ""}>{label}</button>)}</div>
    <div className="mt-5 space-y-5">
      {section === "general" && <SettingGroup title={t("Локализация и формат", "Locale and format")}>
        {select(t("Язык приложения", "App language"), "language", [["ru", "Русский"], ["en", "English"]])}
        {select(t("Стартовый раздел", "Start screen"), "startTab", [["overview", t("Главная", "Overview")], ["wallets", t("Трейдеры", "Traders")], ["pulse", t("Лента", "Feed")], ["favorites", t("Избранное", "Favorites")], ["account", t("Кабинет", "Account")]])}
        {select(t("Часовой пояс", "Time zone"), "timeZone", [["local", t("Системный", "Device")], ["Europe/Moscow", t("Москва", "Moscow")], ["UTC", "UTC"]])}
        {select(t("Формат даты", "Date format"), "dateFormat", [["short", t("Короткий", "Short")], ["full", t("Полный", "Full")], ["iso", "ISO"]])}
        {select(t("Формат времени", "Time format"), "timeFormat", [["24h", "24H"], ["12h", "12H"]])}
        {select(t("Знаков после запятой", "Money decimals"), "moneyDecimals", [["0", "0"], ["2", "2"], ["4", "4"]])}
        <Toggle label={t("Сокращать большие числа", "Compact large numbers")} checked={p.preferences.compactNumbers} onChange={(value) => pref("compactNumbers", value)}/>
        <Toggle label={t("Показывать абсолютное время", "Show absolute timestamps")} checked={p.preferences.absoluteTime} onChange={(value) => pref("absoluteTime", value)}/>
        <Toggle label={t("Скрывать денежные суммы", "Hide money amounts")} checked={p.preferences.privacy} onChange={(value) => pref("privacy", value)}/>
      </SettingGroup>}

      {section === "interface" && <>
        <SettingGroup title={t("Вид и доступность", "Appearance and accessibility")}>
          {select(t("Плотность", "Density"), "density", [["compact", t("Компактно", "Compact")], ["comfortable", t("Свободно", "Comfortable")]])}
          {select(t("Размер текста", "Text size"), "fontScale", [["small", t("Мелкий", "Small")], ["normal", t("Обычный", "Normal")], ["large", t("Крупный", "Large")]])}
          <Toggle label={t("Повышенный контраст", "High contrast")} checked={p.preferences.highContrast} onChange={(value) => pref("highContrast", value)}/>
          <Toggle label={t("Уменьшить анимации", "Reduce motion")} checked={p.preferences.reducedMotion} onChange={(value) => pref("reducedMotion", value)}/>
          <Toggle label={t("Крупные области нажатия", "Large tap targets")} checked={p.preferences.largeTargets} onChange={(value) => pref("largeTargets", value)}/>
          <Toggle label={t("Закреплять верхнее меню", "Sticky header")} checked={p.preferences.stickyHeader} onChange={(value) => pref("stickyHeader", value)}/>
          <Toggle label={t("Показывать предупреждения", "Show warnings")} checked={p.preferences.showWarnings} onChange={(value) => pref("showWarnings", value)}/>
          <Toggle label={t("Подсвечивать строки", "Highlight rows on hover")} checked={p.preferences.rowHover} onChange={(value) => pref("rowHover", value)}/>
          <Toggle label={t("Чередовать фон строк", "Zebra rows")} checked={p.preferences.zebraRows} onChange={(value) => pref("zebraRows", value)}/>
        </SettingGroup>
        <SettingGroup title={t("Блоки главной", "Overview blocks")}>
          <Toggle label={t("Верхняя лента сделок", "Top activity ticker")} checked={p.preferences.showTicker} onChange={(value) => pref("showTicker", value)}/>
          <Toggle label={t("Приостановить ленту", "Pause ticker")} checked={p.preferences.tickerPaused} onChange={(value) => pref("tickerPaused", value)}/>
          <Toggle label={t("Цены рынков", "Market prices")} checked={p.preferences.showMarketStrip} onChange={(value) => pref("showMarketStrip", value)}/>
          <Toggle label={t("Сводка метрик", "Summary metrics")} checked={p.preferences.showSummary} onChange={(value) => pref("showSummary", value)}/>
          <Toggle label={t("Совпадения кошельков", "Wallet confluences")} checked={p.preferences.showConfluences} onChange={(value) => pref("showConfluences", value)}/>
          <Toggle label={t("Недавно просмотренные", "Recently viewed")} checked={p.preferences.showRecent} onChange={(value) => pref("showRecent", value)}/>
          <Toggle label={t("Последняя активность", "Latest activity")} checked={p.preferences.showLatest} onChange={(value) => pref("showLatest", value)}/>
        </SettingGroup>
      </>}

      {section === "ranking" && <>
        <SettingGroup title={t("Сортировка и таблица", "Sorting and table")}>
          {select(t("Сортировка", "Sort by"), "walletSort", [["rank", t("Качество", "Quality")], ["accountValue", "Account"], ["dayPnl", "24H PnL"], ["monthPnl", "30D PnL"], ["monthRoi", "30D ROI"], ["dayVolume", "24H volume"]])}
          {select(t("Направление", "Direction"), "sortDirection", [["asc", t("По возрастанию", "Ascending")], ["desc", t("По убыванию", "Descending")]])}
          {select(t("Строк на странице", "Rows per page"), "pageSize", [["10", "10"], ["25", "25"], ["50", "50"], ["100", "100"]])}
          <Toggle label={t("Избранные первыми", "Favorites first")} checked={p.preferences.favoritesFirst} onChange={(value) => pref("favoritesFirst", value)}/>
          <Toggle label={t("Показывать качество", "Show quality badge")} checked={p.preferences.showQuality} onChange={(value) => pref("showQuality", value)}/>
          <Toggle label={t("Показывать risk-флаги", "Show risk flags")} checked={p.preferences.showRisk} onChange={(value) => pref("showRisk", value)}/>
          <Toggle label={t("Показывать адреса", "Show addresses")} checked={p.preferences.showAddresses} onChange={(value) => pref("showAddresses", value)}/>
          <Toggle label="Account" checked={p.preferences.showAccountColumn} onChange={(value) => pref("showAccountColumn", value)}/>
          <Toggle label="24H PnL" checked={p.preferences.showDayPnlColumn} onChange={(value) => pref("showDayPnlColumn", value)}/>
          <Toggle label="30D PnL" checked={p.preferences.showMonthPnlColumn} onChange={(value) => pref("showMonthPnlColumn", value)}/>
          <Toggle label="30D ROI" checked={p.preferences.showRoiColumn} onChange={(value) => pref("showRoiColumn", value)}/>
          <Toggle label="24H volume" checked={p.preferences.showVolumeColumn} onChange={(value) => pref("showVolumeColumn", value)}/>
        </SettingGroup>
        <SettingGroup title={t("Фильтры по умолчанию", "Default filters")}>
          {select(t("Результат", "Performance"), "walletPerformance", [["all", t("Все", "All")], ["winners", t("В плюсе", "Winners")], ["losers", t("В минусе", "Losers")]])}
          <NumberFilter label={t("Минимальный капитал, $", "Minimum account, $")} value={p.preferences.minAccount} onChange={(value) => pref("minAccount", value)}/>
          <NumberFilter label={t("Минимальный 30D PnL, $", "Minimum 30D PnL, $")} value={p.preferences.minMonthPnl} onChange={(value) => pref("minMonthPnl", value)}/>
          <NumberFilter label={t("Минимальный 30D ROI, %", "Minimum 30D ROI, %")} value={p.preferences.minRoi} onChange={(value) => pref("minRoi", value)}/>
          <NumberFilter label={t("Минимальный объём 24H, $", "Minimum 24H volume, $")} value={p.preferences.minVolume} onChange={(value) => pref("minVolume", value)}/>
          <Toggle label={t("Только кошельки с именем", "Named wallets only")} checked={p.preferences.namedOnly} onChange={(value) => pref("namedOnly", value)}/>
          <Toggle label={t("Только избранные", "Favorites only")} checked={p.preferences.favoritesOnly} onChange={(value) => pref("favoritesOnly", value)}/>
          <Toggle label={t("Без risk-флагов", "No risk flags")} checked={p.preferences.riskFreeOnly} onChange={(value) => pref("riskFreeOnly", value)}/>
        </SettingGroup>
      </>}

      {section === "feed" && <>
        <SettingGroup title={t("Живая лента", "Live feed")}>
          <FilterSelect label={t("Рынок", "Market")} value={p.preferences.activityCoin} onChange={(value) => pref("activityCoin", value)} options={[["all", t("Все", "All")], ...Object.keys(p.prices).map((coin) => [coin, coin])]}/>
          {select(t("Действие", "Action"), "activityAction", [["all", t("Все", "All")], ["long", "Long / Buy"], ["short", "Short / Sell"], ["reduced", t("Сокращения", "Reductions")]])}
          {select(t("Сортировка ленты", "Feed order"), "activitySort", [["newest", t("Сначала новые", "Newest first")], ["largest", t("Сначала крупные", "Largest first")]])}
          {select(t("Событий на экране", "Events per screen"), "activityLimit", [["25", "25"], ["50", "50"], ["100", "100"], ["250", "250"]])}
          <NumberFilter label={t("Минимальная сумма, $", "Minimum notional, $")} value={p.preferences.activityMinNotional} onChange={(value) => pref("activityMinNotional", value)}/>
          <Toggle label={t("Только избранные", "Favorites only")} checked={p.preferences.activityFavoritesOnly} onChange={(value) => pref("activityFavoritesOnly", value)}/>
          <Toggle label={t("Рыночные BUY/SELL", "Market BUY/SELL events")} checked={p.preferences.showMarketTrades} onChange={(value) => pref("showMarketTrades", value)}/>
          <Toggle label={t("Точные Open/Close", "Exact Open/Close events")} checked={p.preferences.showExactTrades} onChange={(value) => pref("showExactTrades", value)}/>
          <FilterSelect label={t("Минимум для верхней ленты", "Top ticker minimum")} value={String(p.preferences.signalThreshold)} onChange={(value) => pref("signalThreshold", Number(value))} options={[["1000", "$1K"], ["5000", "$5K"], ["10000", "$10K"], ["25000", "$25K"], ["100000", "$100K"]]}/>
          <FilterSelect label={t("Окно совпадения", "Confluence window")} value={String(p.preferences.confluenceMinutes)} onChange={(value) => pref("confluenceMinutes", Number(value))} options={[["5", "5 min"], ["15", "15 min"], ["30", "30 min"], ["60", "1 hour"], ["120", "2 hours"], ["240", "4 hours"], ["1440", "24 hours"]]}/>
        </SettingGroup>
        <SettingGroup title={t("Рынки на главной", "Overview markets")}><div className="flex flex-wrap gap-2">{Object.keys(p.prices).map((coin) => <button key={coin} onClick={() => { const next = new Set(p.preferences.hiddenMarkets); if (next.has(coin)) next.delete(coin); else next.add(coin); pref("hiddenMarkets", [...next]); }} className={`market-toggle ${p.preferences.hiddenMarkets.includes(coin) ? "opacity-45" : "active"}`}>{coin}</button>)}</div></SettingGroup>
      </>}

      {section === "notifications" && <SettingGroup title={t("Telegram-уведомления", "Telegram notifications")}>
        <div className="rounded-md border border-[var(--line)] bg-[var(--panel-2)] px-3 py-2.5"><div className="flex items-center justify-between gap-3 text-xs"><span>{p.chatLinked ? t("Telegram подключён", "Telegram connected") : t("Запусти бота командой /start", "Start the bot with /start")}</span><i className={`size-2 rounded-full ${p.chatLinked ? "bg-[var(--cyan)]" : "bg-[var(--warn)]"}`}/></div><p className="mt-1 text-[10px] text-[var(--muted)]">{t("В отслеживании", "Watching")}: {p.favoritesCount}</p></div>
        <Toggle label={t("Уведомления включены", "Notifications enabled")} checked={p.notificationSettings.enabled} onChange={(enabled) => update({ enabled })}/>
        <Toggle label={t("Только открытия, закрытия и перевороты", "Open, close and flip only")} checked={p.notificationSettings.openCloseOnly} onChange={(openCloseOnly) => update({ openCloseOnly })}/>
        <Toggle label={t("Увеличение позиции", "Position increases")} checked={p.notificationSettings.includeAdds} onChange={(includeAdds) => update({ includeAdds })}/>
        <Toggle label={t("Сокращение позиции", "Position reductions")} checked={p.notificationSettings.includeReductions} onChange={(includeReductions) => update({ includeReductions })}/>
        <NumberFilter label={t("Минимальная сумма сделки, $", "Minimum trade amount, $")} value={p.notificationSettings.minNotional} onChange={(minNotional) => update({ minNotional })}/>
        <label className="block text-[10px] text-[var(--muted)]">{t("Монеты через запятую · пусто = все", "Comma-separated coins · empty = all")}<input value={p.notificationSettings.coins.join(", ")} onChange={(event) => update({ coins: event.target.value.split(",").map((coin) => coin.trim().toUpperCase()).filter(Boolean) })} placeholder="BTC, ETH, HYPE" className="control-field mt-2 w-full"/></label>
        <div className="grid grid-cols-2 gap-2"><label className="text-[10px] text-[var(--muted)]">{t("Тихо с", "Quiet from")}<input type="time" value={p.notificationSettings.quietStart} onChange={(event) => update({ quietStart: event.target.value })} className="control-field mt-2 w-full"/></label><label className="text-[10px] text-[var(--muted)]">{t("Тихо до", "Quiet until")}<input type="time" value={p.notificationSettings.quietEnd} onChange={(event) => update({ quietEnd: event.target.value })} className="control-field mt-2 w-full"/></label></div>
        <Toggle label={t("Только совпадения 2+ кошельков", "Only 2+ wallet confluences")} checked={p.notificationSettings.confluenceOnly} onChange={(confluenceOnly) => update({ confluenceOnly })}/>
        <FilterSelect label={t("Часовой пояс уведомлений", "Notification time zone")} value={p.notificationSettings.timezone} onChange={(timezone) => update({ timezone })} options={[["Europe/Moscow", t("Москва", "Moscow")], ["UTC", "UTC"]]}/>
      </SettingGroup>}

      <button onClick={p.onSaveNotifications} disabled={p.notificationSaving} className="sticky bottom-0 h-11 w-full rounded-md bg-[var(--cyan)] text-xs font-semibold text-[#041110] shadow-[0_-12px_30px_#080808] disabled:opacity-50">{p.notificationSaving ? t("Сохраняем…", "Saving…") : t("Сохранить личные настройки", "Save personal settings")}</button>
      <SettingGroup title={t("Состояние", "Status")}><dl className="space-y-3"><Detail label={t("Интернет", "Internet")} value={p.online ? t("Онлайн", "Online") : t("Офлайн", "Offline")}/><Detail label="WebSocket" value={p.live ? t("Подключён", "Connected") : t("Переподключение", "Reconnecting")}/><Detail label={t("Последнее событие", "Last event")} value={p.time(p.lastMessage)}/><Detail label={t("Переподключения", "Reconnects")} value={String(p.reconnects)}/></dl></SettingGroup>
    </div>
  </Drawer>;
}
function WalletInspector({ wallet, note, tag, favorite, money, onFavorite, onCopy, onClose, onSave }: { wallet: WalletRow; note: string; tag: string; favorite: boolean; money(value: number): string; onFavorite(): void; onCopy(value: string, message?: string): void; onClose(): void; onSave(note: string, tag: string): void }) { const [draftNote, setDraftNote] = useState(note); const [draftTag, setDraftTag] = useState(tag); const language = useContext(LanguageContext); const t = (ru: string, en: string) => text(language, ru, en); return <Drawer title={wallet.name} note={short(wallet.address)} onClose={onClose}><div className="space-y-5"><div className="grid grid-cols-2 gap-px overflow-hidden rounded-lg border border-[var(--line)] bg-[var(--line)]"><MetricCard label="Account" value={money(wallet.accountValue)}/><MetricCard label="30D PnL" value={money(wallet.monthPnl)} tone={wallet.monthPnl >= 0 ? "gain" : "loss"}/><MetricCard label="30D ROI" value={`${wallet.monthRoi.toFixed(1)}%`}/><MetricCard label="24H volume" value={money(wallet.dayVolume)}/></div><div><p className="mb-2 text-[10px] uppercase text-[var(--muted)]">Risk flags</p><div className="flex flex-wrap gap-2">{walletRiskFlags(wallet).length ? walletRiskFlags(wallet).map((flag) => <span key={flag} className="risk-chip">{riskText(language, flag)}</span>) : <span className="quality-badge quality-elite">{t("Нет флагов", "No flags")}</span>}</div></div><label className="block text-[10px] text-[var(--muted)]">{t("Моя метка", "My tag")}<input value={draftTag} maxLength={24} onChange={(event) => setDraftTag(event.target.value)} placeholder={t("Например: скальпер", "For example: scalper")} className="control-field mt-2 w-full"/></label><label className="block text-[10px] text-[var(--muted)]">{t("Личная заметка", "Private note")}<textarea value={draftNote} maxLength={500} onChange={(event) => setDraftNote(event.target.value)} placeholder={t("Что важно помнить", "What matters to remember")} className="control-field mt-2 min-h-28 w-full resize-y py-3"/></label><div className="grid grid-cols-2 gap-2"><button onClick={onFavorite} className="control-field flex items-center justify-center gap-2"><Icon name="star" size={14} filled={favorite}/>{favorite ? t("В избранном", "Favorited") : t("В избранное", "Add favorite")}</button><button onClick={() => onCopy(wallet.address, t("Адрес скопирован", "Address copied"))} className="control-field flex items-center justify-center gap-2"><Icon name="copy" size={14}/>{t("Адрес", "Address")}</button><Link href={`/wallet/${wallet.address}`} className="control-field col-span-2 flex items-center justify-center gap-2 text-[var(--cyan)]">{t("Открыть профиль", "Open profile")}<Icon name="arrow" size={13}/></Link><button onClick={() => onSave(draftNote.trim(), draftTag.trim())} className="col-span-2 h-10 rounded-md bg-[var(--cyan)] text-xs font-semibold text-[#041110]">{t("Сохранить карточку", "Save card")}</button></div></div></Drawer>; }
function CompareDialog({ wallets, money, onClose, onRemove }: { wallets: WalletRow[]; money(value: number): string; onClose(): void; onRemove(address: string): void }) { const t = useT(); const metrics: [string, (wallet: WalletRow) => string][] = [["Account", (w) => money(w.accountValue)], ["24H PnL", (w) => money(w.dayPnl)], ["7D PnL", (w) => money(w.weekPnl)], ["30D PnL", (w) => money(w.monthPnl)], ["30D ROI", (w) => `${w.monthRoi.toFixed(1)}%`], ["24H volume", (w) => money(w.dayVolume)], [t("Качество", "Quality"), qualityBand], ["Risk flags", (w) => String(walletRiskFlags(w).length)]]; return <Modal title={t("Сравнение трейдеров", "Compare traders")} note={t("До четырёх аккаунтов рядом", "Up to four accounts side by side")} onClose={onClose}><div className="overflow-x-auto"><table className="w-full min-w-[640px] text-left text-xs"><thead><tr><th className="p-3 text-[var(--muted)]">{t("Метрика", "Metric")}</th>{wallets.map((wallet) => <th key={wallet.address} className="p-3"><span className="block max-w-40 truncate">{wallet.name}</span><button onClick={() => onRemove(wallet.address)} className="mt-1 text-[9px] text-[var(--loss)]">{t("Убрать", "Remove")}</button></th>)}</tr></thead><tbody>{metrics.map(([label, get]) => <tr key={label} className="border-t border-[var(--line)]"><td className="p-3 text-[var(--muted)]">{label}</td>{wallets.map((wallet) => <td key={wallet.address} className="mono p-3">{get(wallet)}</td>)}</tr>)}</tbody></table></div></Modal>; }
function CommandPalette({ query, setQuery, commands, onClose }: { query: string; setQuery(value: string): void; commands: { label: string; detail: string; run(): void }[]; onClose(): void }) { const t = useT(); return <Modal title={t("Командная строка", "Command palette")} note={t("Навигация и быстрые действия · Esc закрыть", "Navigation and quick actions · Esc to close")} onClose={onClose}><label className="control-field flex items-center gap-2"><Icon name="search" size={15}/><input autoFocus value={query} onChange={(event) => setQuery(event.target.value)} placeholder={t("Введите команду…", "Type a command…")} className="min-w-0 flex-1 bg-transparent outline-none"/></label><div className="mt-3 divide-y divide-[var(--line)] overflow-hidden rounded-lg border border-[var(--line)]">{commands.length ? commands.map((command) => <button key={command.label} onClick={() => { command.run(); onClose(); }} className="flex w-full items-center justify-between gap-3 px-4 py-3 text-left hover:bg-white/[.035]"><span className="text-xs font-medium">{command.label}</span><span className="text-[10px] text-[var(--muted)]">{command.detail}</span></button>) : <Empty text={t("Команда не найдена.", "No command found.")}/>}</div></Modal>; }
function useDialogFocus(onClose: () => void) {
  const ref = useRef<HTMLElement | null>(null); const closeRef = useRef(onClose);
  useEffect(() => { closeRef.current = onClose; }, [onClose]);
  useEffect(() => {
    const previous = document.activeElement instanceof HTMLElement ? document.activeElement : null; const dialog = ref.current;
    const background = [...document.querySelectorAll<HTMLElement>(".dc-app > :not(.overlay):not(.toast)")].map((element) => [element, element.inert] as const);
    background.forEach(([element]) => { element.inert = true; });
    const focusable = () => [...(dialog?.querySelectorAll<HTMLElement>('button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])') ?? [])];
    requestAnimationFrame(() => (focusable()[0] ?? dialog)?.focus());
    const onKey = (event: KeyboardEvent) => { if (event.key === "Escape") { event.preventDefault(); closeRef.current(); return; } if (event.key !== "Tab") return; const items = focusable(); if (!items.length) { event.preventDefault(); dialog?.focus(); return; } const first = items[0]; const last = items.at(-1); if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); } };
    document.addEventListener("keydown", onKey); return () => { document.removeEventListener("keydown", onKey); background.forEach(([element, inert]) => { element.inert = inert; }); previous?.focus(); };
  }, []);
  return ref;
}
function Drawer({ title, note, onClose, children }: { title: string; note: string; onClose(): void; children: React.ReactNode }) { const ref = useDialogFocus(onClose); const titleId = useId(); return <div className="overlay" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><aside ref={ref} tabIndex={-1} role="dialog" aria-modal="true" aria-labelledby={titleId} className="drawer"><DialogHead title={title} titleId={titleId} note={note} onClose={onClose}/><div className="overflow-y-auto p-4">{children}</div></aside></div>; }
function Modal({ title, note, onClose, children }: { title: string; note: string; onClose(): void; children: React.ReactNode }) { const ref = useDialogFocus(onClose); const titleId = useId(); return <div className="overlay items-start justify-center p-3 pt-[8vh]" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section ref={ref} tabIndex={-1} role="dialog" aria-modal="true" aria-labelledby={titleId} className="modal-panel"><DialogHead title={title} titleId={titleId} note={note} onClose={onClose}/><div className="p-4">{children}</div></section></div>; }
function DialogHead({ title, titleId, note, onClose }: { title: string; titleId: string; note: string; onClose(): void }) { const t = useT(); return <div className="flex items-center justify-between border-b border-[var(--line)] p-4"><div><h2 id={titleId} className="text-base font-semibold">{title}</h2><p className="mt-1 text-[10px] text-[var(--muted)]">{note}</p></div><button onClick={onClose} className="icon-button" aria-label={t("Закрыть", "Close")}><Icon name="close" size={16}/></button></div>; }

function PanelHead({ title, note, action, onAction }: { title: string; note: string; action?: string; onAction?: () => void }) { return <div className="flex min-h-14 items-center justify-between gap-3 border-b border-[var(--line)] px-4 py-3"><div><h2 className="text-sm font-semibold">{title}</h2><p className="mt-0.5 text-[10px] text-[var(--muted)]">{note}</p></div>{action && onAction && <button onClick={onAction} className="compact-action">{action}<Icon name="arrow" size={13}/></button>}</div>; }
function MetricCard({ label, value, tone }: { label: string; value: string; tone?: "gain" | "loss" | "warn" }) { return <div className="border-b border-r border-[var(--line)] bg-[var(--panel)] px-4 py-3"><p className="text-[9px] uppercase tracking-[.06em] text-[var(--muted)]">{label}</p><p className={`mono mt-1 truncate text-base font-semibold ${tone === "gain" ? "text-[var(--cyan)]" : tone === "loss" ? "text-[var(--loss)]" : tone === "warn" ? "text-[var(--warn)]" : "text-white"}`}>{value}</p></div>; }
function Summary({ label, value, accent = false }: { label: string; value: string; accent?: boolean }) { return <div className="border-r border-[var(--line)] px-3 py-2.5 last:border-r-0 sm:px-4"><p className="text-[9px] uppercase text-[var(--muted)]">{label}</p><p className={`mono mt-1 text-sm font-semibold ${accent ? "text-[var(--cyan)]" : "text-white"}`}>{value}</p></div>; }
function Cell({ label, value, className = "" }: { label: string; value: React.ReactNode; className?: string }) { return <div className={`${className} mt-3 min-w-0 lg:mt-0 lg:text-right`}><p className="text-[9px] uppercase text-[var(--muted)] lg:hidden">{label}</p><div className="mono mt-1 truncate text-xs lg:mt-0">{value}</div></div>; }
function Pnl({ value, suffix = "", money }: { value: number; suffix?: string; money(value: number): string }) { return <span className={value >= 0 ? "text-[var(--cyan)]" : "text-[var(--loss)]"}>{value >= 0 ? "+" : ""}{suffix ? value.toFixed(1) : money(value)}{suffix}</span>; }
function Empty({ text }: { text: string }) { return <p className="px-5 py-12 text-center text-xs text-[var(--muted)]">{text}</p>; }
function EmptyState({ title, text, action, onAction }: { title: string; text: string; action: string; onAction(): void }) { return <div className="px-5 py-16 text-center"><div className="mx-auto flex size-10 items-center justify-center rounded-full border border-[var(--line)] text-[var(--muted)]"><Icon name="search" size={17}/></div><h3 className="mt-3 text-sm font-semibold">{title}</h3><p className="mt-1 text-xs text-[var(--muted)]">{text}</p><button onClick={onAction} className="compact-action mt-4 border border-[var(--line)]">{action}</button></div>; }
function Toggle({ label, checked, onChange }: { label: string; checked: boolean; onChange(value: boolean): void }) { return <label className="flex min-h-9 cursor-pointer items-center justify-between gap-3 rounded-md border border-[var(--line)] bg-[var(--panel-2)] px-3 text-[11px]"><span>{label}</span><input type="checkbox" checked={checked} onChange={(event) => onChange(event.target.checked)} className="toggle-input"/></label>; }
function NumberFilter({ label, value, onChange }: { label: string; value: number; onChange(value: number): void }) { return <label className="text-[10px] text-[var(--muted)]">{label}<input type="number" min="0" value={value || ""} onChange={(event) => onChange(Math.max(0, Number(event.target.value)))} placeholder="0" className="control-field mt-2 w-full"/></label>; }
function FilterSelect({ label, value, onChange, options }: { label: string; value: string; onChange(value: string): void; options: string[][] }) { return <label className="text-[10px] text-[var(--muted)]">{label}<select value={value} onChange={(event) => onChange(event.target.value)} className="control-field mt-2 w-full">{options.map(([option, text]) => <option key={option} value={option}>{text}</option>)}</select></label>; }
function SettingGroup({ title, children }: { title: string; children: React.ReactNode }) { return <section><h3 className="mb-3 text-[10px] font-semibold uppercase tracking-[.1em] text-[var(--muted)]">{title}</h3><div className="space-y-2">{children}</div></section>; }
function Detail({ label, value }: { label: string; value: string }) { return <div className="flex items-center justify-between gap-3"><dt className="text-[11px] text-[var(--muted)]">{label}</dt><dd className="mono text-[11px]">{value}</dd></div>; }
function NavButton({ item, active, onClick }: { item: NavItem; active: boolean; onClick(): void }) { return <button onClick={onClick} aria-current={active ? "page" : undefined} className={`relative flex min-h-14 min-w-0 flex-1 flex-col items-center justify-center gap-1 px-1 text-[9px] font-medium md:min-h-9 md:flex-none md:flex-row md:gap-2 md:rounded-md md:px-3 md:text-xs ${active ? "text-[var(--cyan)] md:bg-[#5ee3dc12]" : "text-[var(--muted)] hover:text-white"}`}><Icon name={item.icon} size={16} filled={item.icon === "star" && active}/><span className="max-w-full truncate md:hidden">{item.mobileLabel ?? item.label}</span><span className="hidden md:inline">{item.label}</span>{active && <i className="absolute inset-x-3 top-0 h-px bg-[var(--cyan)] md:hidden"/>}</button>; }
function Icon({ name, size = 18, filled = false }: { name: IconName; size?: number; filled?: boolean }) { const paths: Record<IconName, React.ReactNode> = { home: <><path d="m4 10 8-6 8 6"/><path d="M6 9v10h12V9M10 19v-6h4v6"/></>, pulse: <path d="M3 12h4l2.2-6 4.1 12 2.2-6H21"/>, wallet: <><rect x="3" y="5" width="18" height="14" rx="3"/><path d="M15 10h6v4h-6a2 2 0 0 1 0-4Z"/></>, star: <path d="m12 3 2.7 5.5 6.1.9-4.4 4.3 1 6.1-5.4-2.9-5.4 2.9 1-6.1-4.4-4.3 6.1-.9L12 3z"/>, user: <><circle cx="12" cy="8" r="4"/><path d="M4.5 21a7.5 7.5 0 0 1 15 0"/></>, search: <><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></>, arrow: <><path d="M5 12h14"/><path d="m14 7 5 5-5 5"/></>, refresh: <><path d="M20 7v5h-5M4 17v-5h5"/><path d="M6.1 9a7 7 0 0 1 11.4-2L20 9M4 15l2.5 2a7 7 0 0 0 11.4-2"/></>, shield: <><path d="M12 3 5 6v5c0 4.6 2.8 8 7 10 4.2-2 7-5.4 7-10V6l-7-3Z"/><path d="M9 12h6M12 9v6"/></>, settings: <><circle cx="12" cy="12" r="3"/><path d="M19 12a7 7 0 1 1-14 0 7 7 0 0 1 14 0ZM12 2v3M12 19v3M2 12h3M19 12h3"/></>, copy: <><rect x="8" y="8" width="11" height="11" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/></>, download: <><path d="M12 3v12m-4-4 4 4 4-4"/><path d="M4 19h16"/></>, filter: <path d="M4 6h16M7 12h10M10 18h4"/>, close: <path d="m6 6 12 12M18 6 6 18"/>, command: <><rect x="4" y="4" width="16" height="16" rx="4"/><path d="M8 9h8M8 13h5"/></>, eye: <><path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="2.5"/></> }; return <svg aria-hidden="true" width={size} height={size} viewBox="0 0 24 24" fill={filled ? "currentColor" : "none"} stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">{paths[name]}</svg>; }
